using System.Text.Json;
using FutureClassroom.Core.Data;
using FutureClassroom.Core.Helpers;
using FutureClassroom.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace FutureClassroom.Api.Services;

public class LessonService(AppDbContext db)
{
    private static readonly JsonSerializerOptions _caseInsensitive = new()
    {
        PropertyNameCaseInsensitive = true,
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower
    };

    public async Task<LessonDetailResponse?> GetLessonAsync(string lessonId, CancellationToken ct = default)
    {
        var aiResult = await db.AiResults
            .AsNoTracking()
            .Where(r => r.LessonId == lessonId)
            .OrderByDescending(r => r.CreatedAt)
            .FirstOrDefaultAsync(ct);

        if (aiResult is not null)
        {
            string? videoPath = CourseHelper.BuildVideoKey(aiResult.Semester, aiResult.CourseId, aiResult.ClassSection, aiResult.GeneratedAt.Value);

            var course = await db.Courses
                .AsNoTracking()
                .Where(c => c.CourseKey == aiResult.CourseKey)
                .Select(c => new { c.Name, c.Section })
                .FirstOrDefaultAsync(ct);

            var expectedGroups = JsonSerializer.Deserialize<List<string>>(aiResult.ExpectedGroupsJson) ?? [];
            var completedGroups = JsonSerializer.Deserialize<List<string>>(aiResult.CompletedGroupsJson) ?? [];
            var missingGroups = JsonSerializer.Deserialize<List<string>>(aiResult.MissingGroupsJson) ?? [];
            var duration = aiResult.WindowSeconds > 0 && aiResult.TotalWindows > 0
                                  ? (int?)(aiResult.WindowSeconds * aiResult.TotalWindows)
                                  : null;

            var metadata = new LessonMetadataDto(
                Semester: aiResult.Semester,
                CourseId: aiResult.CourseId,
                CourseKey: aiResult.CourseKey,
                CourseName: course?.Name ?? "",
                LessonId: lessonId,
                ClassSection: aiResult.ClassSection,
                Week: aiResult.Week,
                RecordDate: aiResult.RecordDate?.ToString("yyyy-MM-dd") ?? "",
                LessonDate: aiResult.LessonDate?.ToString("yyyy-MM-dd") ?? "",
                CreatedAt: aiResult.CreatedAt.ToString("o"),
                GeneratedAt: aiResult.GeneratedAt?.ToString("o"),
                ExpectedGroups: expectedGroups,
                CompletedGroups: completedGroups,
                MissingGroups: missingGroups,
                Duration: duration,
                VideoPath: videoPath,
                IsScreenshotGenerated: aiResult.IsScreenshotGenerated
            );

            var result = await BuildResultFromDbAsync(lessonId, ct);

            return new LessonDetailResponse(Metadata: metadata, Result: result);
        }

        return null;
    }

    public async Task<LatestLessonsResponse> GetLatestLessonsAsync(int limit, CancellationToken ct = default)
    {
        var safeLimit = Math.Clamp(limit, 1, 20);

        var latestResults = await db.AiResults
            .AsNoTracking()
            .Where(r => r.IsScreenshotGenerated)
            .OrderByDescending(r => r.GeneratedAt.HasValue)
            .ThenByDescending(r => r.GeneratedAt)
            .ThenByDescending(r => r.CreatedAt)
            .Take(safeLimit)
            .Select(r => new
            {
                r.LessonId,
                r.CourseKey,
                r.CourseId,
                r.ClassSection,
                r.LessonDate,
                r.GeneratedAt,
                r.CreatedAt
            })
            .ToListAsync(ct);

        if (latestResults.Count == 0)
            return new LatestLessonsResponse([]);

        var courseKeys = latestResults.Select(r => r.CourseKey).Distinct().ToList();
        var courses = await db.Courses
            .AsNoTracking()
            .Where(c => courseKeys.Contains(c.CourseKey))
            .Select(c => new { c.CourseKey, c.Name, c.Section, c.SchedulesJson })
            .ToDictionaryAsync(c => c.CourseKey, ct);

        var lessons = latestResults.Select(result =>
        {
            courses.TryGetValue(result.CourseKey, out var course);

            return new LatestLessonDto(
                LessonId: result.LessonId,
                CourseKey: result.CourseKey,
                CourseName: course?.Name ?? "",
                CourseId: result.CourseId,
                CourseSection: result.ClassSection,
                CourseSchedule: course?.SchedulesJson is null
                    ? []
                    : JsonSerializer.Deserialize<List<CourseScheduleDto>>(course.SchedulesJson, _caseInsensitive) ?? [],
                LessonDate: result.LessonDate?.ToString("yyyy-MM-dd"),
                GeneratedAt: result.GeneratedAt?.ToString("o"),
                CreatedAt: result.CreatedAt.ToString("o")
            );
        }).ToList();

        return new LatestLessonsResponse(lessons);
    }

    private async Task<LessonResultDto?> BuildResultFromDbAsync(string lessonId, CancellationToken ct)
    {
        var windows = await db.AiWindows
            .AsNoTracking()
            .Where(w => w.LessonId == lessonId)
            .OrderBy(w => w.WindowIndex)
            .ToListAsync(ct);

        if (windows.Count == 0) return null;

        var seats = await db.AiWindowSeats
            .AsNoTracking()
            .Where(s => s.LessonId == lessonId)
            .ToListAsync(ct);

        // group seats by (WindowIndex, SeatKey) for fast lookup
        var seatsByWindow = seats
            .GroupBy(s => s.WindowIndex)
            .ToDictionary(
                g => g.Key,
                g => g.GroupBy(s => s.SeatKey)
                      .ToDictionary(
                          sg => sg.Key,
                          sg => sg.ToDictionary(s => s.EngagementLevel, s => s.Value)
                      )
            );

        var classSlices = new List<EngagementSliceDto>();
        var groupSlices = new Dictionary<string, List<EngagementSliceDto>>();

        foreach (var win in windows)
        {
            if (!seatsByWindow.TryGetValue(win.WindowIndex, out var winSeats)) continue;

            var byGroup = winSeats
                .GroupBy(kvp => kvp.Key.Contains('_') ? kvp.Key[..kvp.Key.IndexOf('_')] : kvp.Key)
                .ToDictionary(g => g.Key, g => g.Select(kvp => kvp.Value).ToList());

            // class average: average across all seats in this window
            var allSeatLevels = winSeats.Values.ToList();
            classSlices.Add(new EngagementSliceDto(win.WindowIndex, AverageEngagements(allSeatLevels)));

            // group (table) averages
            foreach (var (groupKey, seatLevels) in byGroup)
            {
                if (!groupSlices.ContainsKey(groupKey))
                    groupSlices[groupKey] = [];
                groupSlices[groupKey].Add(new EngagementSliceDto(win.WindowIndex, AverageEngagements(seatLevels)));
            }
        }

        return new LessonResultDto(groupSlices, classSlices);
    }

    private static List<int> AverageEngagements(List<Dictionary<string, double>> seats)
    {
        var sum = new double[4];
        foreach (var seat in seats)
            for (var level = 0; level < 4; level++)
                sum[level] += seat.GetValueOrDefault(level.ToString());
        return FractionsToPercentages(sum.Select(v => v / seats.Count));
    }

    private static List<int> FractionsToPercentages(IEnumerable<double> fractions)
    {
        var pcts = fractions.Select(f => (int)Math.Round(f * 100)).ToList();
        var diff = 100 - pcts.Sum();
        if (diff != 0 && pcts.Count > 0) pcts[^1] = Math.Max(0, pcts[^1] + diff);
        return pcts;
    }

}

