namespace FutureClassroom.Core.Data;

// One row per lesson (upserted on each AI push). Structured metadata for fast querying.
// Full windows JSON is stored in MinIO at a deterministic path — see VideoService.GetAnalysisResultPath.
public class AiResult {
    public int Id { get; set; }
    public string LessonId { get; set; } = "";        // {semester}_{courseId}_{section}_{week}
    public string CourseKey { get; set; } = "";        // {semester}_{courseId}_{section}
    public string Semester { get; set; } = "";
    public string CourseId { get; set; } = "";
    public string ClassSection { get; set; } = "";
    public string Week { get; set; } = "";
    public DateTime? GeneratedAt { get; set; }
    public int WindowSeconds { get; set; }             // seconds per analysis window
    public int TotalWindows { get; set; }              // duration = WindowSeconds * TotalWindows
    public string ExpectedGroupsJson { get; set; } = "[]";
    public string CompletedGroupsJson { get; set; } = "[]";
    public string MissingGroupsJson { get; set; } = "[]";
    public DateOnly? RecordDate { get; set; }
    public DateOnly? LessonDate { get; set; }
    public bool IsScreenshotGenerated { get; set; } = false;
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
}

