import { ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Checkbox } from "@/components/ui/Checkbox";
import Tooltip from "@/components/Tooltip";
import Image from "@/components/AppImage";
import Link from "next/link";
import mockLessons from "@/mock-lessons.json";
import { exportCourseReportPdf } from "@/utils/export-course-report-pdf";
import {
  formatCourseSchedule,
  formatCourseScheduleTime,
} from "@/utils/course-schedule";
import EngagementMiniChart from "@/components/EngagementMiniChart";

export default function CourseDetailPage() {
  const router = useRouter();
  const { courseKey } = useParams();
  const [courseDetail, setCourseDetail] = useState<any>(null);
  const [selectedLessonIds, setSelectedLessonIds] = useState<Set<string>>(
    new Set(),
  );
  const [dateSortOrder, setDateSortOrder] = useState<"asc" | "desc">("asc");

  const getSemester = (courseKey: string) => {
    if (!courseKey) return "";
    const semesterCode = courseKey.slice(0, 4);
    return `${semesterCode.slice(0, 3)}-${semesterCode.slice(3)}`;
  };

  const formatWeekNumber = (weekNumber: number) => `第${weekNumber}週`;

  const formatDate = (dateString: string) => {
    if (!dateString) return "";
    const parts = dateString.split("-");
    if (parts.length < 3) return dateString;
    return `${parts[1]}月${parts[2].substring(0, 2)}日`;
  };

  const formatCourseDetail = (data: any, key: string) => {
    return {
      ...data,
      semester: getSemester(key),
      enrolled: data.enrolled_count ?? data.enrolled,
      capacity: data.max_capacity ?? data.capacity,
      course_schedule: formatCourseSchedule(data.course_schedule),
      course_schedule_time: formatCourseScheduleTime(data.course_schedule),
      lessons: (data.lessons || []).map((lesson: any) => {
        const status = lesson.status;
        return {
          ...lesson,
          status,
          processText:
            lesson.processText ??
            (status === "analyzing" ? "資料分析中" : undefined),
          errorText:
            lesson.errorText ??
            (status === "error" ? "請聯絡資訊組" : undefined),
        };
      }),
    };
  };

  const getMockCourseDetail = (key: string) => {
    const decodedKey = decodeURIComponent(key);
    return mockLessons.find(
      (lesson: any) => decodeURIComponent(lesson.course_key) === decodedKey,
    );
  };

  const fetchLessons = async (key: string) => {
    try {
      const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
      const baseUrl = `${basePath}/api`;

      const response = await fetch(
        `${baseUrl}/courses/${encodeURIComponent(key)}/lessons`,
        {
          method: "GET",
          headers: { accept: "*/*" },
        },
      );

      if (!response.ok) throw new Error("Failed to fetch lessons from API");

      const resBody = await response.json();
      setCourseDetail(formatCourseDetail(resBody, key));
      console.log("Fetched lessons from API");
    } catch (error) {
      console.error(error);
      // const mockLessonsData = getMockCourseDetail(key);
      // setCourseDetail(
      //   mockLessonsData ? formatCourseDetail(mockLessonsData, key) : null,
      // );
    }
  };

  useEffect(() => {
    if (!courseKey || courseKey === "undefined") return;
    fetchLessons(String(courseKey));
    setSelectedLessonIds(new Set());
    setDateSortOrder("asc");
  }, [courseKey]);

  const lessons = courseDetail?.lessons || [];
  const sortedLessons = useMemo(
    () =>
      [...lessons].sort((a: any, b: any) => {
        const dateA = a.lesson_date ?? "";
        const dateB = b.lesson_date ?? "";
        return dateSortOrder === "asc"
          ? dateA.localeCompare(dateB)
          : dateB.localeCompare(dateA);
      }),
    [lessons, dateSortOrder],
  );

  const toggleDateSort = () => {
    setDateSortOrder((prev) => (prev === "asc" ? "desc" : "asc"));
  };
  const selectedCount = selectedLessonIds.size;
  const allLessonsSelected =
    lessons.length > 0 &&
    lessons.every((lesson: any) => selectedLessonIds.has(lesson.lesson_id));
  const someLessonsSelected = selectedCount > 0 && !allLessonsSelected;

  const toggleLessonSelection = (lessonId: string) => {
    setSelectedLessonIds((prev) => {
      const next = new Set(prev);
      if (next.has(lessonId)) {
        next.delete(lessonId);
      } else {
        next.add(lessonId);
      }
      return next;
    });
  };

  const toggleAllLessons = () => {
    if (allLessonsSelected) {
      setSelectedLessonIds(new Set());
      return;
    }
    setSelectedLessonIds(
      new Set(lessons.map((lesson: any) => lesson.lesson_id)),
    );
  };

  const handleRowClick = (courseKey: string, lesson_id: string) => {
    router.push(`/course/${courseKey}/lesson/${lesson_id}`);
  };

  const handleExportReport = () => {
    const selectedLessons = sortedLessons.filter((lesson: any) =>
      selectedLessonIds.has(lesson.lesson_id),
    );
    exportCourseReportPdf(courseDetail?.course_name, selectedLessons);
  };

  return (
    <div className="p-4 md:p-8 bg-[rgba(242,242,242,1)] min-h-screen">
      {/* Header / Breadcrumbs */}
      <header className="mb-[40px] flex justify-between items-start">
        <div className="space-y-2">
          <div className="flex items-start gap-4">
            <Tooltip
              content="回上一頁"
              showQuestionMark={false}
              showArrow={false}
              triggerMode="hover"
            >
              <Link
                href="/course"
                className="relative group w-8 h-8 bg-white rounded-full flex items-center justify-center text-gray-90"
              >
                <ArrowLeft size={18} />
              </Link>
            </Tooltip>
            <div className="flex-1">
              <h1 className="headline-3-reg text-gray-90 mb-2 leading-snug">
                課程週覽
              </h1>
            </div>
          </div>

          <div className="flex flex-col gap-2">
            <h1 className="headline-1-sb text-gray-90 flex items-center gap-2">
              {courseDetail?.course_name}
            </h1>
            <div className="flex flex-wrap gap-2">
              {courseDetail?.semester && (
                <Tag text={courseDetail?.semester} hint={"學年期"} />
              )}
              {courseDetail?.course_id && (
                <Tag text={courseDetail?.course_id} hint={"課程識別碼"} />
              )}
              {courseDetail?.course_section && (
                <Tag text={courseDetail?.course_section} hint={"班次"} />
              )}
              {courseDetail?.course_schedule && (
                <Tag
                  text={courseDetail?.course_schedule}
                  hint={courseDetail?.course_schedule_time}
                />
              )}
            </div>
          </div>
        </div>

        <div className="text-right">
          <div className="body-1-reg text-gray-70 mb-1">已選上</div>
          <div className="text-[40px] font-semibold text-gray-90">
            {courseDetail?.enrolled}
            <span className="text-gray-70 body-1-reg">
              /{courseDetail?.capacity}
            </span>
          </div>
        </div>
      </header>

      {/* Main Table */}
      <main className="bg-white rounded-[24px] shadow-sm overflow-hidden p-4 lg:p-0 md:h-[636px] md:flex md:flex-col">
        <div className="overflow-x-auto md:overflow-y-auto md:flex-1">
          <table className="w-full border-collapse block lg:table">
            <thead className="lg:sticky lg:top-0 lg:z-10 lg:bg-white">
              {/* header(>=1024px) */}
              <tr className="hidden lg:table-row h-[80px] bg-white border-b border-[rgba(0,0,0,0.1)] text-gray-70 body-3-reg">
                <th className="py-5 pl-5 pr-0 w-[80px] min-w-[48px] max-w-[80px] align-middle">
                  <div className="bg-[rgba(6,45,65,0.05)] h-12 flex items-center justify-center rounded-l-[12px]">
                    <Checkbox
                      checked={allLessonsSelected}
                      // indeterminate={someLessonsSelected}
                      onChange={toggleAllLessons}
                      onClick={(e) => e.stopPropagation()}
                    />
                  </div>
                </th>

                <th className="py-5 px-0 body-1-reg text-gray-70 w-[240px] text-left">
                  <div className="bg-[rgba(6,45,65,0.05)] h-12 flex items-center pr-4 lg:pl-6">
                    <div className="flex items-center gap-1">
                      日期{" "}
                      <Tooltip
                        content={
                          dateSortOrder === "asc"
                            ? "由舊到新排序"
                            : "由新到舊排序"
                        }
                        showQuestionMark={false}
                        showArrow={false}
                        triggerMode="hover"
                      >
                        <button
                          onClick={toggleDateSort}
                          className="cursor-pointer"
                        >
                          <div className="w-[32px] h-[32px] rounded-full flex items-center justify-center hover:bg-[rgba(6,45,65,0.05)]">
                            <Image
                              src={
                                dateSortOrder === "asc"
                                  ? "/icon/function/icon_sorting-down.svg"
                                  : "/icon/function/icon_sorting-up.svg"
                              }
                              alt={
                                dateSortOrder === "asc"
                                  ? "由舊到新排序"
                                  : "由新到舊排序"
                              }
                              width={24}
                              height={24}
                            />
                          </div>
                        </button>
                      </Tooltip>
                    </div>
                  </div>
                </th>

                <th className="py-5 px-0 body-1-reg text-gray-70 text-left">
                  <div className="bg-[rgba(6,45,65,0.05)] h-12 flex items-center px-2 lg:px-6">
                    課程進度
                  </div>
                </th>

                <th className="py-5 pl-0 pr-5 body-1-reg text-gray-70 w-[184px] min-w-[184px] max-w-[184px] text-left">
                  <div className="bg-[rgba(6,45,65,0.05)] h-12 flex items-center pl-4 pr-5 lg:pr-6 rounded-r-[12px]">
                    投入程度
                  </div>
                </th>
              </tr>
              {/* header(<1024px) */}
              <tr className="flex lg:hidden bg-[rgba(6,45,65,0.05)] rounded-[12px] p-3 mb-2 items-center gap-3">
                <th className="w-6 flex items-center justify-center">
                  <Checkbox
                    checked={allLessonsSelected}
                    indeterminate={someLessonsSelected}
                    onChange={toggleAllLessons}
                    onClick={(e) => e.stopPropagation()}
                  />
                </th>
                <th className="body-1-reg text-gray-70 flex items-center gap-1">
                  <div className="flex items-center gap-1">
                    日期{" "}
                    <Tooltip
                      content={
                        dateSortOrder === "asc"
                          ? "由舊到新排序"
                          : "由新到舊排序"
                      }
                      showQuestionMark={false}
                      showArrow={false}
                      triggerMode="hover"
                    >
                      <button
                        onClick={toggleDateSort}
                        className="cursor-pointer"
                      >
                        <div className="w-[32px] h-[32px] rounded-full flex items-center justify-center hover:bg-[rgba(6,45,65,0.05)]">
                          <Image
                            src={
                              dateSortOrder === "asc"
                                ? "/icon/function/icon_sorting-down.svg"
                                : "/icon/function/icon_sorting-up.svg"
                            }
                            alt={
                              dateSortOrder === "asc"
                                ? "由舊到新排序"
                                : "由新到舊排序"
                            }
