                        </span>
                        {/* 日期 */}
                        <span className="title-1 text-gray-90 whitespace-nowrap">
                          {formatDate(lesson.lesson_date)}
                        </span>
                        {/* New 標籤 */}
                        {lesson.isNew && (
                          <span className="body-3-reg px-[6px] py-[1px] bg-info-10 text-info-50 rounded-[4px] text-[12px]">
                            New
