                        )}
                      </div>

                      {/* 課程進度(<1024px) */}
                      <div className="block lg:hidden w-full mt-1">
                        <div className="w-full border border-gray-300 rounded-[20px] px-4 py-2 bg-white text-gray-80 text-sm truncate">
                          {lesson.topic}
                        </div>
                      </div>
                    </div>
                  </td>

                  {/* 課程進度(>=1024px) */}
                  <td className="hidden lg:table-cell py-5 px-6 text-gray-90 body-1-reg leading-relaxed">
                    {lesson.topic}
                  </td>

                  {/* 投入程度 */}
                  <td className="hidden lg:table-cell py-5 pl-4 pr-6 w-[184px] min-w-[184px] max-w-[184px]">
                    <StatusContent
                      status={lesson.status}
                      errorText={lesson.errorText}
                      processText={lesson.processText}
                      lessonId={lesson.lesson_id}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <footer className="mt-auto pt-4 pb-4 px-4 lg:px-6 flex justify-end bg-white border-t border-[rgba(0,0,0,0.05)] shrink-0">
          <Button
            variant="primary"
            size="large"
            disabled={selectedCount === 0}
            className="gap-2"
            onClick={handleExportReport}
          >
            {selectedCount > 0 ? (
              <>
                <Image
                  src="/icon/function/icon_download-white.svg"
                  alt="Download"
                  width={18}
                  height={18}
                />
                <span className="body-1-reg text-white">
                  匯出報告 ({selectedCount})
                </span>
              </>
            ) : (
              <>
                <Image
                  src="/icon/function/icon_download-gray.svg"
                  alt="Download"
                  width={18}
                  height={18}
                />
                <span className="body-1-reg text-gray-30">匯出報告</span>
              </>
            )}
          </Button>
        </footer>
      </main>
