function StatusContent({
  status,
  errorText,
  processText,
  lessonId,
}: {
  status: string;
  errorText?: string;
  processText?: string;
  lessonId?: string;
}) {
  if (status === "completed" && lessonId) {
    return <EngagementMiniChart lessonId={lessonId} />;
  }
  if (status === "error") {
    return (
      <div className="flex items-center justify-start gap-1 text-danger-50 bg-danger-10 px-3 py-1.5 rounded-lg body-1-reg w-fit whitespace-nowrap">
        <Image
          src="/icon/function/icon_warning_filled.svg"
          alt="Error"
          width={16}
          height={16}
        />
        {errorText}
      </div>
    );
  }
  if (status === "analyzing") {
    return (
      <div className="flex items-center justify-start gap-1 text-warning-50 bg-warning-10 px-3 py-1.5 rounded-lg body-1-reg w-fit whitespace-nowrap">
        <Image
          src="/icon/function/icon_in-progress-yellow.svg"
          alt="In Progress"
          width={16}
          height={16}
        />
        {processText}
      </div>
    );
  }
  return <div className="h-12" />;
}

function Tag({ text, hint }: { text: string; hint: string }) {
  return (
    <Tooltip
      content={hint}
      showQuestionMark={false}
      showArrow={false}
      triggerMode="hover"
    >
      <span className="px-3 py-2 bg-[rgba(6,45,65,0.05)] text-gray-90 body-1-reg rounded-lg block whitespace-nowrap">
        {text}
      </span>
    </Tooltip>
  );
}

