"use client";
import Image from "@/components/AppImage";
import { CSSProperties, ReactNode, useState, useEffect, useRef } from "react";

type TriggerMode = "hover" | "click" | "pageload";

interface TooltipProps {
  label?: string;
  content: ReactNode;
  showArrow?: boolean;
  showQuestionMark?: boolean;
  triggerMode?: TriggerMode;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
  childrenClassName?: string;
}

const TOOLTIP_EVENT = "GLOBAL_TOOLTIP_EVENT";
let isAnyClickTooltipOpen = false;

export default function Tooltip({
  label,
  content,
  showArrow = true,
  showQuestionMark = true,
  triggerMode = "hover",
  className,
  style,
  children,
  childrenClassName,
}: TooltipProps) {
  const [isVisible, setIsVisible] = useState(triggerMode === "pageload");
  const hideTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const tooltipIdRef = useRef(Math.random().toString(36).substring(2, 9));

  const isClickMode = triggerMode === "click";

  // pageload: auto-dismiss after 3s

