using FutureClassroom.Api.Services;
using FutureClassroom.Core.Data;
using Microsoft.EntityFrameworkCore;

var options = new DbContextOptionsBuilder<AppDbContext>()
    .UseInMemoryDatabase("verify-fallback")
    .Options;

const string courseKey = "1142_247 10050_";

await using (var seed = new AppDbContext(options))
{
    seed.Courses.Add(new Course
    {
        CourseKey = courseKey,
        CourseId = "247 10050",
        Name = "氣候變遷對策：地球急轉彎",
        Semester = "1142",
        Section = "",
        TotalStudentQuota = 40,
        SchedulesJson = null,
    });

    // Deliberately NO Lessons rows for this course — reproduces the reported bug.

    seed.AiResults.Add(new AiResult
    {
        LessonId = $"{courseKey}_14_0527",
        CourseKey = courseKey,
        Semester = "1142",
        CourseId = "247 10050",
        ClassSection = "",
        Week = "14",
        LessonDate = new DateOnly(2026, 5, 27),
        RecordDate = new DateOnly(2026, 5, 27),
        IsScreenshotGenerated = true,
        GeneratedAt = new DateTime(2026, 5, 27, 15, 0, 0, DateTimeKind.Utc),
    });

    // A stray AiResult with no LessonDate should be skipped, not shown as a blank row.
    seed.AiResults.Add(new AiResult
    {
        LessonId = $"{courseKey}_99_0101",
        CourseKey = courseKey,
        Semester = "1142",
        CourseId = "247 10050",
        ClassSection = "",
        Week = "99",
        LessonDate = null,
        IsScreenshotGenerated = false,
    });

    // A different course's AiResult must not leak into this course's fallback list.
    seed.AiResults.Add(new AiResult
    {
        LessonId = "1142_227 M9280__5_0311",
        CourseKey = "1142_227 M9280_",
        Semester = "1142",
        CourseId = "227 M9280",
        ClassSection = "",
        Week = "5",
        LessonDate = new DateOnly(2026, 3, 11),
        IsScreenshotGenerated = true,
    });

    await seed.SaveChangesAsync();
}

await using var db = new AppDbContext(options);
var service = new CourseService(db);
var result = await service.GetCourseLessonsAsync(courseKey);

Console.WriteLine($"IsFallbackSchedule: {result!.IsFallbackSchedule}");
Console.WriteLine($"Lessons.Count: {result.Lessons.Count}");
foreach (var l in result.Lessons)
{
    Console.WriteLine($"  LessonId={l.LessonId} Week={l.WeekNumber} Date={l.LessonDate} Topic=\"{l.Topic}\" Status={l.Status} LastUpdatedAt={l.LastUpdatedAt}");
}

var pass = result.IsFallbackSchedule
    && result.Lessons.Count == 1
    && result.Lessons[0].WeekNumber == 14
    && result.Lessons[0].LessonDate == "2026-05-27"
    && result.Lessons[0].Topic == "課程網無課程進度資訊"
    && result.Lessons[0].Status == "completed";

Console.WriteLine(pass ? "\nPASS" : "\nFAIL");
Environment.Exit(pass ? 0 : 1);

