2	using FutureClassroom.Core.Data;
3	using FutureClassroom.Core.Enumeration;
4	using Microsoft.EntityFrameworkCore;
5	using System.Text.Json;
6	
7	namespace FutureClassroom.Api.Services;
8	
9	public class CourseService(AppDbContext db)
10	{
11	
12	    private static readonly JsonSerializerOptions _caseInsensitive = new()
13	    {
14	        PropertyNameCaseInsensitive = true,
15	        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower
16	    };
17	
18	    public async Task<CoursesResponse> GetCoursesAsync(string? semester)
19	    {
20	        var query = db.Courses.AsQueryable();
21	        if (semester is not null)
22	            query = query.Where(c => c.Semester == semester);
23	
24	        var rawCourses = await query
25	            .Select(c => new { c.CourseId, c.Name, c.Section, c.CourseKey, c.SchedulesJson, c.Semester })
26	            .ToListAsync();
27	
28	        var courseKeys = rawCourses.Select(c => c.CourseKey).ToList();
29	
30	        var lessonStats = await db.AiResults
31	            .Where(r => courseKeys.Contains(r.CourseKey))
32	            .GroupBy(r => r.CourseKey)
33	            .Select(g => new
34	            {
35	                CourseKey = g.Key,
36	                Total = g.Count(),
37	                Completed = g.Count(r => r.IsScreenshotGenerated)
38	            })
39	            .ToDictionaryAsync(x => x.CourseKey, x => x);
40	
41	        var semesters = rawCourses
42	            .GroupBy(c => c.Semester)
43	            .OrderByDescending(g => g.Key)
44	            .Select(g => new SemesterDto(
45	                g.Key,
46	                g.Select(c => new CourseDto(
47	                    CourseId: c.CourseId,
48	                    CourseName: c.Name,
49	                    CourseSection: c.Section ?? "",
50	                    CourseKey: c.CourseKey,
51	                    CourseSchedule: c.SchedulesJson is null
52	                        ? []
53	                        : JsonSerializer.Deserialize<List<CourseScheduleDto>>(c.SchedulesJson, _caseInsensitive) ?? [],
54	                    TotalLessons: lessonStats.TryGetValue(c.CourseKey, out var s) ? s.Total : 0,
55	                    Completed: lessonStats.TryGetValue(c.CourseKey, out var s2) ? s2.Completed : 0
56	                )).ToList()
57	            ))
58	            .ToList();
59	
60	        return new CoursesResponse(semesters);
61	    }
62	
63	    public async Task<CourseLessonsResponse?> GetCourseLessonsAsync(string courseKey)
64	    {
65	        var course = await db.Courses
66	            .Where(c => c.CourseKey == courseKey)
67	            .FirstOrDefaultAsync()
68	            ?? throw new KeyNotFoundException($"Course not found: {courseKey}");
69	
70	        var rawLessons = await db.Lessons
71	            .Where(l => l.CourseKey == courseKey)
