7	
8	type SortOrder = "asc" | "desc";
9	
10	interface DataCardProps {
11	  title: string;
12	  data: any[];
13	  hasChart?: boolean;
14	  hasLastCheckedAt?: boolean;
15	  sortByField?: string;
16	  sortOrder?: SortOrder;
