57	  const sortedData = useMemo(() => {
58	    if (!sortByField) return data;
59	
60	    return [...data].sort((a, b) => {
61	      let valueA = a[sortByField];
62	      let valueB = b[sortByField];
63	
64	      // 處理 undefined 或 null 的狀況
65	      if (valueA === undefined || valueA === null) return 1;
66	      if (valueB === undefined || valueB === null) return -1;
67	
68	      // 特殊處理："XX月XX日" 格式的字串，轉換成可以安全比對的字串數字 (例如 "0217")
69	      if (sortByField === "date") {
70	        valueA = valueA.replace(/[^0-9]/g, "");
71	        valueB = valueB.replace(/[^0-9]/g, "");
72	      }
73	
74	      // 進行排序比對
75	      if (valueA < valueB) {
76	        return sortOrder === "asc" ? -1 : 1;
77	      }
78	      if (valueA > valueB) {
79	        return sortOrder === "asc" ? 1 : -1;
80	      }
81	      return 0;
82	    });
83	  }, [data, sortByField, sortOrder]);
