98	                className="shrink-0 invert brightness-200"
99	              />
100	            </div>
101	          </div>
102	        </Link>
103	      </div>
104	      <div className="flex-1 max-md:overflow-x-hidden pr-1 min-h-0">
105	        {sortedData.map((item, idx) => (
106	          <Link
107	            href={`/course/${item.course_key}/lesson/${item.lesson_id}`}
108	            key={idx}
109	          >
110	            <div
111	              key={idx}
