import Image from "@/components/AppImage";
import TextPreview from "@/components/TextPreview";
import EngagementMiniChart from "@/components/EngagementMiniChart";
import Link from "next/link";
import { useMemo } from "react";
import { formatDate } from "@/utils/time";

type SortOrder = "asc" | "desc";

interface DataCardProps {
  title: string;
  data: any[];
  hasChart?: boolean;
  hasLastCheckedAt?: boolean;
  sortByField?: string;
  sortOrder?: SortOrder;
}

function formatRelativeTime(dateString: string): string {
  if (!dateString) return "";

  const formattedString = dateString.replace(/-/g, "/");
  const date = new Date(formattedString);
  const now = new Date();

  const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);

  if (diffInSeconds < 0) return "剛剛";
  if (diffInSeconds < 60) return "剛剛";

  const diffInMinutes = Math.floor(diffInSeconds / 60);
  if (diffInMinutes < 60) return `${diffInMinutes} 分鐘前`;

  const diffInHours = Math.floor(diffInMinutes / 60);
  if (diffInHours < 24) return `${diffInHours} 小時前`;

  const diffInDays = Math.floor(diffInHours / 24);
  if (diffInDays < 7) return `${diffInDays} 天前`;

  const diffInWeeks = Math.floor(diffInDays / 7);
  if (diffInWeeks < 4) return `${diffInWeeks} 週前`;

  const diffInMonths = Math.floor(diffInDays / 30);
  if (diffInMonths < 12) return `${diffInMonths} 個月前`;

  return `${Math.floor(diffInDays / 365)} 年前`;
}

export default function DataCard({
  title,
  data,
  hasChart = false,
  hasLastCheckedAt = false,
  sortByField = "last_checked_at",
  sortOrder = "desc",
}: DataCardProps) {
  const sortedData = useMemo(() => {
    if (!sortByField) return data;

    return [...data].sort((a, b) => {
      let valueA = a[sortByField];
      let valueB = b[sortByField];

      // 處理 undefined 或 null 的狀況
      if (valueA === undefined || valueA === null) return 1;
      if (valueB === undefined || valueB === null) return -1;

      // 特殊處理："XX月XX日" 格式的字串，轉換成可以安全比對的字串數字 (例如 "0217")
      if (sortByField === "date") {
        valueA = valueA.replace(/[^0-9]/g, "");
        valueB = valueB.replace(/[^0-9]/g, "");
      }

      // 進行排序比對
      if (valueA < valueB) {
        return sortOrder === "asc" ? -1 : 1;
      }
      if (valueA > valueB) {
        return sortOrder === "asc" ? 1 : -1;
      }
      return 0;
    });
  }, [data, sortByField, sortOrder]);

  return (
    <div className="bg-white rounded-[24px] p-6 flex flex-col h-full overflow-auto">
      <div className="flex justify-between items-center mb-2">
        <h3 className="headline-3-sb text-gray-90">{title}</h3>
        <Link href="/course">
          <div className="flex items-center gap-1 cursor-pointer group hover:bg-[rgba(6,45,65,0.05)] rounded-full px-2 py-1">
            <span className="body-2-reg text-gray-90 ">所有課程</span>
            <div className="shrink-0 w-[14px] h-[14px] bg-gray-90 rounded-full flex items-center justify-center">
              <Image
                src="/icon/common/icon_chevron-right.svg"
                alt="View More"
                width={12}
                height={12}
                className="shrink-0 invert brightness-200"
              />
            </div>
          </div>
        </Link>
      </div>
      <div className="flex-1 max-md:overflow-x-hidden pr-1 min-h-0">
        {sortedData.map((item, idx) => (
          <Link
            href={`/course/${item.course_key}/lesson/${item.lesson_id}`}
            key={idx}
          >
            <div
              key={idx}
              className="relative group flex items-center justify-between py-4 px-4 -mx-4 
            gap-2 cursor-pointer 
            hover:bg-[rgba(6,45,65,0.05)] hover:rounded-[8px]
            after:content-[''] 
            after:absolute 
            after:bottom-0 
            after:left-4 
            after:right-4 
            after:border-b 
            after:border-gray-200"
            >
              <div>
                <div className="text-[18px] text-gray-90 mb-1">
                  <TextPreview text={item.name} maxLength={24} />
                </div>
                <div className="flex flex-wrap gap-2">
                  {item.generated_at && (
                    <span className="body-2-reg text-gray-90 bg-gray-10 px-2 py-1 rounded-[4px] group-hover:bg-white">
                      {formatDate(item.generated_at)}
                    </span>
                  )}
                  {item.course_id && (
                    <span className="body-2-reg text-gray-90 bg-gray-10 px-2 py-1 rounded-[4px] group-hover:bg-white">
                      {item.course_id}
                    </span>
                  )}
                  {item.class && (
                    <span className="body-2-reg text-gray-90 bg-gray-10 px-2 py-1 rounded-[4px] group-hover:bg-white">
                      {item.class}
                    </span>
                  )}
                  {item.schedule && (
                    <span className="body-2-reg text-gray-90 bg-gray-10 px-2 py-1 rounded-[4px] group-hover:bg-white">
                      {item.schedule}
                    </span>
                  )}
                </div>
              </div>
              {hasChart && item.lesson_id && (
                <EngagementMiniChart
                  lessonId={item.lesson_id}
                  className="relative w-20 h-10 rounded-md overflow-hidden shrink-0 hidden sm:block pointer-events-none"
                  height={40}
                />
              )}
              {hasLastCheckedAt && item.last_checked_at && (
                <div className="absolute top-4 right-4 body-3-reg text-gray-70">
                  {formatRelativeTime(item.last_checked_at)}
                </div>
              )}
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
}

