"use client";

import { useMemo } from "react";
import { ArrowLeft } from "lucide-react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import EngagementChart from "@/components/EngagementChart";
import VideoPlayer, { VideoPlayerHandle } from "@/components/VideoPlayer";
import SeatMap from "@/components/SeatMap";
import AnalysisMetricCard from "@/components/AnalysisMetricCard";
import Tooltip from "@/components/Tooltip";
import { createTaiwanTimeFormatter } from "@/utils/time";
import { buildChartData, findModeExtrema } from "@/utils/chart";
import { MODE_CONFIGS } from "@/utils/mode";
import { mockAiResultMapping, mockAudioMapping } from "@/utils/mockDataMapping";
import { formatDate } from "@/utils/time";

export default function CourseAnalyticsPage() {
  const [selectedGroup, setSelectedGroup] = useState("class");
  const [chartHoverSeconds, setChartHoverSeconds] = useState<number | null>(
    null,
  );
  const { courseKey, lessonId } = useParams();
  const [lessonDetail, setLessonDetail] = useState<any>(null);
  const [playbackSeconds, setPlaybackSeconds] = useState<number>(0);
  const [videoUrl, setVideoUrl] = useState<string>(""); // TODO: 這是暫時的影片網址
  const videoPlayerRef = useRef<VideoPlayerHandle>(null);
  const chartScrollRef = useRef<HTMLDivElement>(null);
  const [keyframePreviewEl, setKeyframePreviewEl] =
    useState<HTMLDivElement | null>(null);
  const [plotboxWidth, setPlotboxWidth] = useState<number>(0);

  // TODO: Use the actual video url from the API
  const fetchVideo = async () => {
    try {
      throw new Error("Failed to get video/audio from API");
    } catch (error) {
      console.error(error);
      const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
      const path = `${mockAudioMapping[lessonId as keyof typeof mockAudioMapping]}`;
      if (path !== "undefined") {
        const mockAudioPath = `${basePath}${path}`;
        setVideoUrl(mockAudioPath);
        console.log("Fetched video/audio from mock data:", mockAudioPath);
      } else {
        console.error(
          `No mock video/audio data found for lessonId: ${lessonId}`,
        );
      }
    }
  };

  // 由於 DB 資料不一致，先把 groups 的 key 值從 T1 改成 G1 ...
  const normalizeGroupKeys = (groups: Record<string, any> = {}) =>
    Object.keys(groups).reduce(
      (acc, key) => {
        const newKey = key.replace(/^T/, "G");
        acc[newKey] = groups[key];
        return acc;
      },
      {} as Record<string, any>,
    );

  const fetchLessonDetail = async () => {
    try {
      const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
      const response = await fetch(`${basePath}/api/lessons/${lessonId}`);
      if (!response.ok) throw new Error("Failed to fetch lesson detail");
      const resBody = await response.json();
      resBody.result.groups = normalizeGroupKeys(resBody.result.groups);
      setLessonDetail((prev: any) => ({
        ...resBody,
        metadata: {
          ...prev?.metadata,
          ...resBody?.metadata,
        },
      }));
      console.log("Fetched lesson detail from API");
    } catch (error) {
      console.error(error);
      // const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
      // const mockDataPath = `${basePath}${mockAiResultMapping[lessonId as keyof typeof mockAiResultMapping]}`;
      // if (mockDataPath) {
      //   fetch(mockDataPath).then((res: any) => {
      //     if (!res.ok)
      //       throw new Error(`Failed to load mock JSON: ${res.status}`);
      //     return res
      //       .json()
      //       .then((resBody: any) => {
      //         resBody.result.groups = normalizeGroupKeys(resBody.result.groups);
      //         return resBody;
      //       })
      //       .then((jsonData: any) => {
      //         setLessonDetail(jsonData);
      //         console.log("Successfully loaded mock JSON data:", jsonData);
      //       })
      //       .catch((err: any) => {
      //         console.error("Error reading mock JSON file:", err);
      //       });
      //   });
      // } else {
      //   console.error(`No mock AI result found for lessonId: ${lessonId}`);
      // }
    }
  };

  useEffect(() => {
    if (!lessonId || lessonId === "undefined") return;
    fetchVideo();
    fetchLessonDetail();
  }, [lessonId]);

  const fetchCourseDetail = async () => {
    try {
      const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
      const response = await fetch(
        `${basePath}/api/courses/${courseKey}/lessons`,
      );

      if (!response.ok) throw new Error("Failed to fetch course detail");
      const resBody = await response.json();

      const lesson = resBody.lessons.find((item: any) => {
        return (
          decodeURIComponent(item.lesson_id) ===
          decodeURIComponent(lessonId as string)
        );
      });
      setLessonDetail((prevDetail: any) => ({
        ...prevDetail,
        metadata: {
          ...prevDetail?.metadata,
          course_name: resBody.course_name,
          topic: lesson?.topic,
          status: lesson?.status,
          lesson_date: lesson?.lesson_date,
        },
      }));
      console.log("Fetched course detail from API");
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    if (!courseKey || courseKey === "undefined") return;
    fetchCourseDetail();
  }, [courseKey]);

  // 初始化時間格式化器
  const toTaiwanHHMM = useMemo(() => {
    const startTime = lessonDetail?.metadata?.generated_at || "";
    return createTaiwanTimeFormatter(startTime);
  }, [lessonDetail?.metadata?.generated_at]);

  // 計算指標
  const metrics = useMemo(() => {
    // 根據 SeatMap 的選取狀況動態決定資料來源（全班數據 or 某小組數據）
    const currentData =
      selectedGroup === "class"
        ? lessonDetail?.result?.class || []
        : lessonDetail?.result?.groups?.[selectedGroup] || [];

    if (!currentData.length) {
      return { avgList: [], maxTimeList: [], minTimeList: [] };
    }

    const chartData = buildChartData(currentData, toTaiwanHHMM);
    const totalPoints = chartData.length;
    const extrema = findModeExtrema(chartData);

    const avgList = MODE_CONFIGS.map((mode) => {
      const sum = chartData.reduce(
        (acc, point) => acc + (point[mode.key] ?? 0),
        0,
      );
      return (sum / totalPoints).toFixed(1);
    });

    const maxTimeList = MODE_CONFIGS.map(
      (mode) => extrema[mode.key]?.max.name ?? "--",
    );
    const minTimeList = MODE_CONFIGS.map(
      (mode) => extrema[mode.key]?.min.name ?? "--",
    );

    return { avgList, maxTimeList, minTimeList };
  }, [lessonDetail, selectedGroup, toTaiwanHHMM]);

  const [progressFraction, setProgressFraction] = useState<number | null>(null);

  const isPending = lessonDetail?.metadata?.status === "pending";

  const metricCards = (
    <>
      <AnalysisMetricCard
        variant="distribution"
        label={selectedGroup === "class" ? "全班狀態佔比" : "小組狀態佔比"}
        valueList={metrics.avgList}
      />
      <AnalysisMetricCard
        variant="time"
        label={
          <div className="title-2">
            佔比<span className="text-success-40">最高</span>時段
          </div>
        }
        subLabel="各自進行"
        valueList={metrics.maxTimeList}
      />
      <AnalysisMetricCard
        variant="time"
        label={
          <div className="title-2">
            佔比<span className="text-danger-40">最低</span>時段
          </div>
        }
        subLabel="各自進行"
        valueList={metrics.minTimeList}
      />
    </>
  );

  return (
    <div className="min-h-screen bg-[rgba(242,242,242,1)] p-8 font-sans">
      <div className="max-w-[1440px] mx-auto">
        <PageHeader lessonDetail={lessonDetail} />

        {!isPending && (
          <div className="grid grid-cols-1 gap-4 lg:grid-cols-3 mb-4">
            {metricCards}
          </div>
        )}

        <div className="flex flex-col gap-4 lg:grid lg:grid-cols-17">
          <div className="lg:col-span-12 lg:col-start-1 lg:row-start-1">
            <EngagementChart
              status={lessonDetail?.metadata?.status}
              rawClassData={lessonDetail?.result?.class}
              rawGroupData={lessonDetail?.result?.groups}
              completedGroups={lessonDetail?.metadata?.completed_groups}
              selectedGroup={selectedGroup}
              onSelectedGroupChange={setSelectedGroup}
              startTime={lessonDetail?.metadata?.generated_at}
              onChartSeek={(seconds) => videoPlayerRef.current?.seek(seconds)}
              videoSeconds={playbackSeconds}
              onProgressFractionChange={setProgressFraction}
              onPlotboxWidthChange={setPlotboxWidth}
              scrollContainerRef={chartScrollRef}
            />
          </div>

          <div className="lg:col-span-12 lg:col-start-1 lg:row-start-2">
            <VideoPlayer
              ref={videoPlayerRef}
              videoSrc={videoUrl}
              chartHighlightSeconds={chartHoverSeconds}
              onPlaybackTime={setPlaybackSeconds}
              progressFraction={progressFraction ?? 0}
              plotboxWidth={plotboxWidth}
              syncScrollRef={chartScrollRef}
              previewContainer={keyframePreviewEl}
              lessonId={lessonId as string}
              maxDuration={lessonDetail?.metadata?.duration || 0}
              status={lessonDetail?.metadata?.status}
              // 有些課程的資料跟實際影片長度不一致，所以需要用 maxDuration 來限制影片長度
            />
          </div>
          <div className="aspect-video lg:aspect-auto h-auto lg:h-[214px] lg:col-span-5 lg:col-start-13 lg:row-start-2">
            <div ref={setKeyframePreviewEl} className="h-full w-full" />
          </div>

          <div className="lg:col-span-5 lg:col-start-13 lg:row-start-1 h-full">
            <SeatMap
              completedGroups={
                isPending ? [] : lessonDetail?.metadata?.completed_groups
              }
              selectedGroup={selectedGroup}
              onSelectedGroupChange={setSelectedGroup}
              readOnly={isPending}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

function PageHeader({ lessonDetail }: { lessonDetail: any }) {
  const params = useParams();
  const courseKey =
    typeof params.courseKey === "string"
      ? params.courseKey
      : Array.isArray(params.courseKey)
        ? params.courseKey[0]
        : "";

  const displayDate =
    formatDate(lessonDetail?.metadata?.generated_at) ||
    formatDate(lessonDetail?.metadata?.lesson_date);

  return (
    <header className="mb-6">
      <div className="flex items-start gap-4">
        <Tooltip
          content="回上一頁"
          showQuestionMark={false}
          showArrow={false}
          triggerMode="hover"
        >
          <Link
            href={courseKey ? `/course/${courseKey}` : "/course"}
            className="relative group w-8 h-8 bg-white rounded-full flex items-center justify-center text-gray-90"
          >
            <ArrowLeft size={18} />
          </Link>
        </Tooltip>
        <div className="flex-1">
          <h1 className="headline-3-reg text-gray-90 mb-2 leading-snug">
            {lessonDetail?.metadata?.course_name}
          </h1>
        </div>
      </div>
      <div className="mt-2 space-y-1">
        <h2 className="headline-1-sb text-gray-90">{displayDate}</h2>
        <p className="body-1-reg text-gray-70">
          {lessonDetail?.metadata?.topic}
        </p>
      </div>
    </header>
  );
}

