const WEEKDAY_MAPPING: Record<string, string> = {
  "1": "一",
  "2": "二",
  "3": "三",
  "4": "四",
  "5": "五",
  "6": "六",
  "7": "日",
};

type CourseScheduleItem = {
  weekday?: string;
  start_session: string;
  end_session: string;
};

/** 將 course_schedule 陣列轉為 "一, 1-3" 格式；多時段以 " / " 分隔 */
export function formatCourseSchedule(
  courseSchedule: CourseScheduleItem[] | undefined,
): string {
  if (!courseSchedule?.length) return "";
  return courseSchedule
    .map((schedule) => {
      const day =
        WEEKDAY_MAPPING[schedule.weekday ?? ""] || schedule.weekday || "";
      return `${day}, ${schedule.start_session}-${schedule.end_session}`;
    })
    .join(" / ");
}

const SESSION_TIMES: Record<string, { start: string; end: string }> = {
  "0": { start: "07:10", end: "08:00" },
  "1": { start: "08:10", end: "09:00" },
  "2": { start: "09:10", end: "10:00" },
  "3": { start: "10:20", end: "11:10" },
  "4": { start: "11:20", end: "12:10" },
  "5": { start: "12:20", end: "13:10" },
  "6": { start: "13:20", end: "14:10" },
  "7": { start: "14:20", end: "15:10" },
  "8": { start: "15:30", end: "16:20" },
  "9": { start: "16:30", end: "17:20" },
  "10": { start: "17:30", end: "18:20" },
  A: { start: "18:25", end: "19:15" },
  B: { start: "19:20", end: "20:10" },
  C: { start: "20:15", end: "21:05" },
  D: { start: "21:10", end: "22:00" },
};

export function getSessionTimeRange(
  startSession: string,
  endSession: string,
): string {
  const start = SESSION_TIMES[startSession]?.start;
  const end = SESSION_TIMES[endSession]?.end;
  if (!start || !end) return "";
  return `${start} - ${end}`;
}

export function formatCourseScheduleTime(
  courseSchedule: CourseScheduleItem[] | undefined,
): string {
  if (!courseSchedule?.length) return "";
  return courseSchedule
    .map((schedule) =>
      getSessionTimeRange(schedule.start_session, schedule.end_session),
    )
    .filter(Boolean)
    .join(" / ");
}

