export function createTaiwanTimeFormatter(startTime: string) {
    const startMs = new Date(startTime).getTime();

    return (offsetMinutes: number) => {
      const twMs = startMs + offsetMinutes * 60_000 + 8 * 3_600_000;

      const h = Math.floor((twMs / 3_600_000) % 24);
      const m = Math.floor((twMs / 60_000) % 60);

      return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
    };
  }

export function formatDate(dateString?: string | null) {
  if (!dateString) return "";
  const parts = dateString.split("-");
  if (parts.length < 3) return dateString;

  const month = parts[1];
  const day = parts[2].substring(0, 2);

  return `${month}月${day}日`;
}

export function formatFullDate(dateString?: string | null) {
  if (!dateString) return "";

  const date = new Date(dateString);
  if (Number.isNaN(date.getTime())) return "";

  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Taipei",
    year: "numeric",
    month: "numeric",
    day: "numeric",
  }).formatToParts(date);

  const year = parts.find((p) => p.type === "year")?.value;
  const month = parts.find((p) => p.type === "month")?.value;
  const day = parts.find((p) => p.type === "day")?.value;

