export interface RecentlyViewedLesson {
  course_key: string;
  course_id: string;
  class: string;
  schedule: string;
  name: string;
  lesson_id: string;
  generated_at: string | null;
  last_checked_at: string; // "YYYY-MM-DD HH:mm:ss"，本機時間
}

const STORAGE_KEY = "fc_recently_viewed_lessons";
const MAX_STORED = 20; // 儲存上限（緩衝用，避免無限成長；顯示時再取前 N 筆）

function nowAsLocalTimestamp(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(
    d.getHours(),
  )}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function readAll(): RecentlyViewedLesson[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    console.error("Failed to read recently viewed lessons", error);
    return [];
  }
}

export function recordRecentlyViewedLesson(
  entry: Omit<RecentlyViewedLesson, "last_checked_at">,
): void {
  if (typeof window === "undefined") return;
  try {
    const existing = readAll().filter(
      (item) => item.lesson_id !== entry.lesson_id,
    );
    const next = [
      { ...entry, last_checked_at: nowAsLocalTimestamp() },
      ...existing,
    ].slice(0, MAX_STORED);
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
  } catch (error) {
    console.error("Failed to record recently viewed lesson", error);
  }
}

export function getRecentlyViewedLessons(limit = 4): RecentlyViewedLesson[] {
  return readAll()
    .sort((a, b) => b.last_checked_at.localeCompare(a.last_checked_at))
    .slice(0, limit);
}

