function nowAsLocalTimestamp() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}
const ts = nowAsLocalTimestamp();
console.log("generated timestamp:", ts);
const formatted = ts.replace(/-/g, "/");
const date = new Date(formatted);
console.log("parsed back:", date.toString());
console.log("diff seconds from now:", Math.floor((Date.now() - date.getTime())/1000));
'

