1	using System.Text.Json;
2	using FutureClassroom.Core.Data;
3	using FutureClassroom.Core.Helpers;
4	using FutureClassroom.Api.Models;
5	using Microsoft.EntityFrameworkCore;
6	
7	namespace FutureClassroom.Api.Services;
8	
9	public class LessonService(AppDbContext db)
10	{
11	    private static readonly JsonSerializerOptions _caseInsensitive = new()
12	    {
13	        PropertyNameCaseInsensitive = true,
14	        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower
15	    };
16	
17	    public async Task<LessonDetailResponse?> GetLessonAsync(string lessonId, CancellationToken ct = default)
18	    {
19	        var aiResult = await db.AiResults
20	            .AsNoTracking()
21	            .Where(r => r.LessonId == lessonId)
22	            .OrderByDescending(r => r.CreatedAt)
23	            .FirstOrDefaultAsync(ct);
24	
25	        if (aiResult is not null)
26	        {
27	            string? videoPath = CourseHelper.BuildVideoKey(aiResult.Semester, aiResult.CourseId, aiResult.ClassSection, aiResult.GeneratedAt.Value);
28	
29	            var course = await db.Courses
30	                .AsNoTracking()
31	                .Where(c => c.CourseKey == aiResult.CourseKey)
32	                .Select(c => new { c.Name, c.Section })
33	                .FirstOrDefaultAsync(ct);
34	
35	            var expectedGroups = JsonSerializer.Deserialize<List<string>>(aiResult.ExpectedGroupsJson) ?? [];
36	            var completedGroups = JsonSerializer.Deserialize<List<string>>(aiResult.CompletedGroupsJson) ?? [];
37	            var missingGroups = JsonSerializer.Deserialize<List<string>>(aiResult.MissingGroupsJson) ?? [];
38	            var duration = aiResult.WindowSeconds > 0 && aiResult.TotalWindows > 0
39	                                  ? (int?)(aiResult.WindowSeconds * aiResult.TotalWindows)
40	                                  : null;
41	
42	            var metadata = new LessonMetadataDto(
43	                Semester: aiResult.Semester,
44	                CourseId: aiResult.CourseId,
45	                CourseKey: aiResult.CourseKey,
46	                CourseName: course?.Name ?? "",
47	                LessonId: lessonId,
48	                ClassSection: aiResult.ClassSection,
49	                Week: aiResult.Week,
50	                RecordDate: aiResult.RecordDate?.ToString("yyyy-MM-dd") ?? "",
51	                LessonDate: aiResult.LessonDate?.ToString("yyyy-MM-dd") ?? "",
52	                CreatedAt: aiResult.CreatedAt.ToString("o"),
53	                GeneratedAt: aiResult.GeneratedAt?.ToString("o"),
54	                ExpectedGroups: expectedGroups,
55	                CompletedGroups: completedGroups,
56	                MissingGroups: missingGroups,
57	                Duration: duration,
58	                VideoPath: videoPath,
59	                IsScreenshotGenerated: aiResult.IsScreenshotGenerated
60	            );
61	
62	            var result = await BuildResultFromDbAsync(lessonId, ct);
63	
64	            return new LessonDetailResponse(Metadata: metadata, Result: result);
65	        }
66	
67	        return null;
68	    }
69	
70	    public async Task<LatestLessonsResponse> GetLatestLessonsAsync(int limit, CancellationToken ct = default)
71	    {
72	        var safeLimit = Math.Clamp(limit, 1, 20);
73	
74	        var latestResults = await db.AiResults
75	            .AsNoTracking()
76	            .Where(r => r.IsScreenshotGenerated)
77	            .OrderByDescending(r => r.GeneratedAt.HasValue)
78	            .ThenByDescending(r => r.GeneratedAt)
79	            .ThenByDescending(r => r.CreatedAt)
80	            .Take(safeLimit)
81	            .Select(r => new
82	            {
83	                r.LessonId,
84	                r.CourseKey,
85	                r.CourseId,
86	                r.ClassSection,
87	                r.LessonDate,
88	                r.GeneratedAt,
89	                r.CreatedAt
90	            })
91	            .ToListAsync(ct);
92	
93	        if (latestResults.Count == 0)
94	            return new LatestLessonsResponse([]);
95	
96	        var courseKeys = latestResults.Select(r => r.CourseKey).Distinct().ToList();
97	        var courses = await db.Courses
98	            .AsNoTracking()
99	            .Where(c => courseKeys.Contains(c.CourseKey))
100	            .Select(c => new { c.CourseKey, c.Name, c.Section, c.SchedulesJson })
101	            .ToDictionaryAsync(c => c.CourseKey, ct);
102	
103	        var lessons = latestResults.Select(result =>
104	        {
105	            courses.TryGetValue(result.CourseKey, out var course);
106	
107	            return new LatestLessonDto(
108	                LessonId: result.LessonId,
109	                CourseKey: result.CourseKey,
110	                CourseName: course?.Name ?? "",
111	                CourseId: result.CourseId,
112	                CourseSection: result.ClassSection,
113	                CourseSchedule: course?.SchedulesJson is null
114	                    ? []
115	                    : JsonSerializer.Deserialize<List<CourseScheduleDto>>(course.SchedulesJson, _caseInsensitive) ?? [],
116	                LessonDate: result.LessonDate?.ToString("yyyy-MM-dd"),
117	                GeneratedAt: result.GeneratedAt?.ToString("o"),
118	                CreatedAt: result.CreatedAt.ToString("o")
119	            );
120	        }).ToList();
121	
122	        return new LatestLessonsResponse(lessons);
123	    }
124	
125	    private async Task<LessonResultDto?> BuildResultFromDbAsync(string lessonId, CancellationToken ct)
126	    {
127	        var windows = await db.AiWindows
128	            .AsNoTracking()
129	            .Where(w => w.LessonId == lessonId)
130	            .OrderBy(w => w.WindowIndex)
131	            .ToListAsync(ct);
132	
133	        if (windows.Count == 0) return null;
134	
135	        var seats = await db.AiWindowSeats
136	            .AsNoTracking()
137	            .Where(s => s.LessonId == lessonId)
138	            .ToListAsync(ct);
139	
140	        // group seats by (WindowIndex, SeatKey) for fast lookup
141	        var seatsByWindow = seats
142	            .GroupBy(s => s.WindowIndex)
143	            .ToDictionary(
144	                g => g.Key,
145	                g => g.GroupBy(s => s.SeatKey)
146	                      .ToDictionary(
147	                          sg => sg.Key,
148	                          sg => sg.ToDictionary(s => s.EngagementLevel, s => s.Value)
149	                      )
150	            );
151	
152	        var classSlices = new List<EngagementSliceDto>();
153	        var groupSlices = new Dictionary<string, List<EngagementSliceDto>>();
154	
155	        foreach (var win in windows)
156	        {
157	            if (!seatsByWindow.TryGetValue(win.WindowIndex, out var winSeats)) continue;
158	
159	            var byGroup = winSeats
160	                .GroupBy(kvp => kvp.Key.Contains('_') ? kvp.Key[..kvp.Key.IndexOf('_')] : kvp.Key)
161	                .ToDictionary(g => g.Key, g => g.Select(kvp => kvp.Value).ToList());
162	
163	            // class average: average across all seats in this window
164	            var allSeatLevels = winSeats.Values.ToList();
165	            classSlices.Add(new EngagementSliceDto(win.WindowIndex, AverageEngagements(allSeatLevels)));
166	
167	            // group (table) averages
168	            foreach (var (groupKey, seatLevels) in byGroup)
169	            {
170	                if (!groupSlices.ContainsKey(groupKey))
171	                    groupSlices[groupKey] = [];
172	                groupSlices[groupKey].Add(new EngagementSliceDto(win.WindowIndex, AverageEngagements(seatLevels)));
173	            }
174	        }
175	
176	        return new LessonResultDto(groupSlices, classSlices);
177	    }
178	
179	    private static List<int> AverageEngagements(List<Dictionary<string, double>> seats)
180	    {
181	        var sum = new double[4];
182	        foreach (var seat in seats)
183	            for (var level = 0; level < 4; level++)
184	                sum[level] += seat.GetValueOrDefault(level.ToString());
185	        return FractionsToPercentages(sum.Select(v => v / seats.Count));
186	    }
187	
188	    private static List<int> FractionsToPercentages(IEnumerable<double> fractions)
189	    {
190	        var pcts = fractions.Select(f => (int)Math.Round(f * 100)).ToList();
191	        var diff = 100 - pcts.Sum();
192	        if (diff != 0 && pcts.Count > 0) pcts[^1] = Math.Max(0, pcts[^1] + diff);
193	        return pcts;
194	    }
195	
196	}
