// Largest-remainder method: round each bucket down, then hand out the leftover
// 1-point increments to whichever buckets had the biggest fractional remainder.
// Dumping the whole rounding deficit onto a single fixed bucket (e.g. always the
// last one) can fail when that bucket has already rounded down to 0 and there's
// nothing left to take away, letting the total drift above 100.
private static List<int> FractionsToPercentages(IEnumerable<double> fractions)
{
    var raw = fractions.Select(f => f * 100).ToList();
    var pcts = raw.Select(v => (int)Math.Floor(v)).ToList();
    var deficit = 100 - pcts.Sum();

    var byRemainderDesc = raw
        .Select((v, i) => (Index: i, Remainder: v - Math.Floor(v)))
        .OrderByDescending(r => r.Remainder)
        .ToList();

    for (var i = 0; i < deficit && i < byRemainderDesc.Count; i++)
        pcts[byRemainderDesc[i].Index]++;

    return pcts;
}

