using Amazon.S3;
using Amazon.S3.Model;
using FutureClassroom.Core.Data;
using FutureClassroom.Core.Helpers;
using Microsoft.EntityFrameworkCore;
using System.Diagnostics;

namespace FutureClassroom.Job.Jobs.Implement;

/// <summary>
/// 影片截圖
/// </summary>
/// <param name="dbFactory"></param>
/// <param name="minIO"></param>
/// <param name="config"></param>
/// <param name="logger"></param>
public class VideoScreenshot : IVideoScreenshot
{
    private readonly ILogger<VideoScreenshot> _logger;
    private readonly IDbContextFactory<AppDbContext> _dbFactory;
    private readonly IAmazonS3 _minIO;
    private readonly IAmazonS3 _s3;
    private readonly IConfiguration _config;

    private string? _minIO_bucket;
    private string? _s3_bucket;
    private string? _ffmpeg;
    private string? _mediaRoot;

    public VideoScreenshot(ILogger<VideoScreenshot> logger, IDbContextFactory<AppDbContext> dbFactory, [FromKeyedServices("minio")] IAmazonS3 minIO, [FromKeyedServices("s3")] IAmazonS3 s3, IConfiguration config)
    {
        _logger = logger;
        _dbFactory = dbFactory;
        _minIO = minIO;
        _s3 = s3;
        _config = config;

        _minIO_bucket = config["MinIO:Bucket"];
        _s3_bucket = config["S3:Bucket"];
        _ffmpeg = config["Ffmpeg:Path"];
        _mediaRoot = config["Screenshot:MediaRoot"];
    }

    public async Task ExecuteAsync()
    {
        if (string.IsNullOrWhiteSpace(_minIO_bucket))
        {
            _logger.LogError("MinIO:Bucket is not configured.");
            return;
        }
        if (string.IsNullOrWhiteSpace(_s3_bucket))
        {
            _logger.LogError("S3:Bucket is not configured.");
            return;
        }
        if (string.IsNullOrWhiteSpace(_ffmpeg))
        {
            _logger.LogError("Ffmpeg:Path is not configured.");
            return;
        }
        if (string.IsNullOrWhiteSpace(_mediaRoot))
        {
            _logger.LogError("Screenshot:MediaRoot is not configured.");
            return;
        }

        _logger.LogInformation("ScreenshotJob started.");
        await using var db = await _dbFactory.CreateDbContextAsync();

        var pending = await db.AiResults.Where(x => !x.IsScreenshotGenerated && x.UpdatedAt >= DateTime.UtcNow.AddDays(-1)).ToListAsync();        


        if (pending.Count == 0)
        {
            _logger.LogInformation("No pending AiResults for screenshot generation.");
            return;
        }

        _logger.LogInformation("Found {Count} AiResult(s) pending screenshot generation.", pending.Count);

        foreach (var result in pending)
        {
            try
            {
                await ProcessAsync(result, db);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process screenshots for LessonId={LessonId}.", result.LessonId);
            }
        }
    }

    private async Task ProcessAsync(AiResult result, AppDbContext db)
    {

#warning M10-401 教室代碼待確認資料來源,目前先寫死為 M10-401
        var videoKey = await ResolveVideoKeyAsync(result);

        if (string.IsNullOrWhiteSpace(videoKey))
        {
            _logger.LogWarning("Cannot resolve video key for LessonId={LessonId}. Skipping.", result.LessonId);
            return;
        }

        var videoFileName = Path.GetFileName(videoKey);
        var lessonThumbDir = Path.Combine(_mediaRoot, result.LessonId, "thumb");
        var localVideoPath = Path.Combine(Path.GetTempPath(), $"{result.LessonId}_{videoFileName}");

        try
        {
            Directory.CreateDirectory(lessonThumbDir);

            _logger.LogInformation("Downloading {Key} from MinIO...", videoKey);
            await DownloadVideoAsync(videoKey, localVideoPath);

            //_logger.LogInformation("Generating original frames for {LessonId}...", result.LessonId);
            //await RunFfmpegAsync(localVideoPath, $"-vf fps=1/60 \"{lessonDir}/original_%04d.jpg\"");

            _logger.LogInformation("Generating images for {LessonId}...", result.LessonId);
            await RunFfmpegAsync(localVideoPath, $"-vf fps=1/60,scale=320:-1 \"{lessonThumbDir}/%04d.jpg\"");

            _logger.LogInformation("Uploading screenshots for {LessonId} to S3...", result.LessonId);
            await UploadScreenshotsAsync(lessonThumbDir, result.LessonId);

            result.IsScreenshotGenerated = true;
            result.UpdatedAt = DateTime.UtcNow;

            await db.SaveChangesAsync();

            _logger.LogInformation("Screenshots completed for LessonId={LessonId}.", result.LessonId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to process screenshots for LessonId={LessonId}. videoKey{videoKey}", result.LessonId, videoKey);
        }
        finally
        {
            if (File.Exists(localVideoPath))
                File.Delete(localVideoPath);
        }
    }

    /// <summary>
    /// 依 GeneratedAt 建立 videoKey，若 MinIO 上找不到檔案則將時間逐次加 1 秒重試，最多加 10 秒。
    /// </summary>
    private async Task<string?> ResolveVideoKeyAsync(AiResult result)
    {
        for (var offset = 0; offset <= 10; offset++)
        {
            var videoKey = CourseHelper.BuildVideoKey(result.Semester, result.CourseId, result.ClassSection, result.GeneratedAt!.Value.AddSeconds(offset));

#if DEBUG
            videoKey = "recordings/114-2/501-11020/02/2026-05-04-14-20-01_114-2_501-11020_02_M10-401_projector.mp4";
#endif

            if (string.IsNullOrWhiteSpace(videoKey))
                return null;

            try
            {
                await _minIO.GetObjectMetadataAsync(new GetObjectMetadataRequest
                {
                    BucketName = _minIO_bucket,
                    Key = videoKey
                });

                if (offset > 0)
                    _logger.LogInformation("Video found for LessonId={LessonId} after adding {Offset} second(s). Key={Key}", result.LessonId, offset, videoKey);

                return videoKey;
            }
            catch (AmazonS3Exception ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
            {
                _logger.LogDebug("Video not found for LessonId={LessonId} at offset {Offset}s. Key={Key}", result.LessonId, offset, videoKey);
            }
        }

        return null;
    }

    private async Task UploadScreenshotsAsync(string lessonDir, string lessonId)
    {
        var files = Directory.GetFiles(lessonDir, "*.jpg");

        foreach (var file in files)
        {
            var fileName = Path.GetFileName(file);
            var safeKey = $"{_mediaRoot}/{lessonId}/thumb/{fileName}".Replace(" ", "_").Replace("\\", "/");
            var s3Key = safeKey;

            await using var fs = File.OpenRead(file);
            await _s3.PutObjectAsync(new PutObjectRequest
            {
                BucketName = _s3_bucket,
                Key = s3Key,
                InputStream = fs,
                ContentType = "image/jpeg"
            });

            _logger.LogDebug("Uploaded {File} to S3 key {Key}.", fileName, s3Key);
        }

        _logger.LogInformation("Uploaded {Count} screenshot(s) for LessonId={LessonId}.", files.Length, lessonId);
    }

    private async Task DownloadVideoAsync(string key, string destPath)
    {
        if (File.Exists(destPath))
            File.Delete(destPath);

        var response = await _minIO.GetObjectAsync(new GetObjectRequest
        {
            BucketName = _minIO_bucket,
            Key = key
        });

        await using var fs = File.Create(destPath);
        await response.ResponseStream.CopyToAsync(fs);
    }

    private async Task RunFfmpegAsync(string inputPath, string outputArgs)
    {
        var args = $"-y -i \"{inputPath}\" {outputArgs}";
        var psi = new ProcessStartInfo(_ffmpeg, args)
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using var process = Process.Start(psi)
            ?? throw new InvalidOperationException($"Failed to start ffmpeg process.");

        var stderr = await process.StandardError.ReadToEndAsync();
        await process.WaitForExitAsync();

        if (process.ExitCode != 0)
            throw new InvalidOperationException($"ffmpeg exited with code {process.ExitCode}: {stderr}");
    }

}

