import React, {
  useState,
  useEffect,
  useMemo,
  useRef,
  useCallback,
  forwardRef,
  useImperativeHandle,
} from "react";
import { createPortal } from "react-dom";
import Image from "@/components/AppImage";
import { mockThumbnailMapping } from "@/utils/mockDataMapping";
import Tooltip from "@/components/Tooltip";

// 時間單位換算: 總秒數 -> hh:mm:ss 或 mm:ss
function formatTime(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return "0:00";
  const total = Math.floor(seconds);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  if (h > 0) {
    return `${h}:${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`; // hh:mm:ss
  }
  return `${m}:${s.toString().padStart(2, "0")}`; // mm:ss
}

// 與分析圖同步：播放、拖曳進度、鍵盤 seek 時回報目前秒數
const THUMB_INTERVAL_SEC = 360;

const RIGHT_MARGIN = 28; // 與 EngagementChart 同步

// 截圖尚未生成時，以藍色漸層色塊代替影格
const PLACEHOLDER_COLORS = [
  "bg-blue-10",
  "bg-blue-20",
  "bg-blue-30",
  "bg-blue-40",
  "bg-blue-50",
  "bg-blue-60",
  "bg-blue-70",
  "bg-blue-80",
  "bg-blue-90",
  "bg-blue-100",
];

export type VideoPlayerHandle = {
  seek: (seconds: number) => void;
};

type VideoPlayerProps = {
  videoSrc?: string;
  onPlaybackTime?: (seconds: number) => void;
  chartHighlightSeconds?: number | null;
  pxPerMinute?: number;
  progressFraction: number;
  plotboxWidth: number;
  syncScrollRef?: React.RefObject<HTMLDivElement | null>;
  previewContainer?: HTMLElement | null;
  maxDuration: number;
  lessonId: string;
  status: string;
};

const VideoPlayer = forwardRef<VideoPlayerHandle, VideoPlayerProps>(
  function VideoPlayer(
    {
      videoSrc,
      onPlaybackTime,
      chartHighlightSeconds,
      pxPerMinute,
      progressFraction,
      plotboxWidth,
      syncScrollRef,
      previewContainer,
      maxDuration,
      lessonId,
      status,
    },
    ref,
  ) {
    const [thumbnails, setThumbnails] = useState<string[]>([]);
    const [currentTime, setCurrentTime] = useState(0);
    const [duration, setDuration] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);
    const [volume, setVolume] = useState(1);
    const [isMuted, setIsMuted] = useState(false);
    const [playbackRate, setPlaybackRate] = useState(1.0);
    const videoRef = useRef<HTMLVideoElement>(null);
    const progressBarRef = useRef<HTMLDivElement>(null);
    const keyframeStripRef = useRef<HTMLDivElement>(null);
    const isFetchingThumbnailsRef = useRef(false);
    const isScrubbingRef = useRef(false);
    const [scrubTime, setScrubTime] = useState<number | null>(null);
    const [isThumbHovered, setIsThumbHovered] = useState(false);
    const [videoLoadFailed, setVideoLoadFailed] = useState(false);
    const [thumbnailFetchSettled, setThumbnailFetchSettled] = useState(false);
    const yAxisGutterPx = 0; // Align with Recharts plot area (yAxisWidth)

    useEffect(() => {
      setVideoLoadFailed(false);
      setThumbnailFetchSettled(false);
    }, [videoSrc]);

    // analyzing = 已有分析資料但截圖還沒生成，用藍色漸層色塊代替
    const hasVideoSource = Boolean(videoSrc) && !videoLoadFailed;
    const showPlaceholderStrip =
      status === "analyzing" &&
      thumbnails.length === 0 &&
      (!hasVideoSource || thumbnailFetchSettled);

    const emitPlaybackTime = useCallback(
      (t: number) => {
        onPlaybackTime?.(t);
      },
      [onPlaybackTime],
    );

    // 沒有影片時改用 metadata 的 duration 當時間軸
    const getTimelineLimit = useCallback(() => {
      const videoDuration = videoRef.current?.duration ?? NaN;
      const hasMedia = Number.isFinite(videoDuration) && videoDuration > 0;
      if (!hasMedia && !showPlaceholderStrip) return 0;
      if (maxDuration && maxDuration > 0) return maxDuration;
      return hasMedia ? videoDuration : 0;
    }, [maxDuration, showPlaceholderStrip]);

    const seekTo = useCallback(
      (seconds: number) => {
        const limit = getTimelineLimit();
        if (limit <= 0) return;

        const video = videoRef.current;
        const hasMedia =
          !!video && Number.isFinite(video.duration) && video.duration > 0;
        // 把秒數限制在 [0, limit] 之間
        const clamped = Math.min(
          Math.max(0, seconds),
          hasMedia ? Math.min(limit, video.duration) : limit,
        );

        if (hasMedia) video.currentTime = clamped;
        setCurrentTime(clamped);
        setScrubTime(null);
        emitPlaybackTime(clamped);
      },
      [emitPlaybackTime, getTimelineLimit],
    );

    useImperativeHandle(
      ref,
      () => ({
        seek: seekTo,
      }),
      [seekTo],
    );

    const fetchThumbnails = async (videoDuration: number) => {
      if (isFetchingThumbnailsRef.current) return;
      isFetchingThumbnailsRef.current = true;

      const interval = THUMB_INTERVAL_SEC;
      try {
        const promises = [];
        const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";

        for (let i = 0; i < videoDuration; i += interval) {
          const minuteIndex = Math.floor(i / 60) + 1;
          const url = `${basePath}/api/image/thumb/${lessonId}/${minuteIndex}`;
          promises.push(
            fetch(url, { method: "GET", headers: { accept: "*/*" } })
              .then((res) => {
                if (!res.ok) {
                  throw new Error(
                    `Thumb ${minuteIndex} response was not ok (Status: ${res.status})`,
                  );
                }
                return res.blob();
              })
              .then((blob) => URL.createObjectURL(blob)),
          );
        }
        const resolvedThumbs = await Promise.all(promises);
        setThumbnails(resolvedThumbs);
        console.log("Fetched thumbnails from API");
      } catch (error: any) {
        console.error("Error fetching thumbnails:", error);
        const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
        const mockThumbnailPath =
          mockThumbnailMapping[lessonId as keyof typeof mockThumbnailMapping];

        if (mockThumbnailPath) {
          const totalCount = Math.floor(videoDuration / interval) + 1;
          const dynamicThumbnails = Array.from(
            { length: totalCount },
            (_, index) => {
              const currentSeconds = index * interval;
              const fileNumber = String(index + 1).padStart(3, "0");
              return `${basePath}${mockThumbnailPath}/shot_${fileNumber}_${currentSeconds}s.jpg`;
            },
          );
          setThumbnails(dynamicThumbnails);
          console.log("Using mock thumbnails for lessonId:", lessonId);
        } else {
          console.error(`No mock thumbnails found for lessonId: ${lessonId}`);
        }
      } finally {
        isFetchingThumbnailsRef.current = false;
        setThumbnailFetchSettled(true);
      }
    };

    // 當影片 Metadata 載入完成，取得正確的 duration 後再開始向 API 要圖片
    const handleLoadedMetadata = useCallback(() => {
      const video = videoRef.current;
      if (!video) return;

      const duration = video.duration;
      setDuration(duration);

      const time = video.currentTime;
      setCurrentTime(time);
      emitPlaybackTime(time);

      if (duration > 0) {
        fetchThumbnails(duration);
      }
    }, [emitPlaybackTime, duration]);

    // 重新載入時釋放記憶體避免 Memory Leak
    useEffect(() => {
      return () => {
        thumbnails.forEach((url) => {
          if (url.startsWith("blob:")) {
            URL.revokeObjectURL(url);
          }
        });
      };
    }, [thumbnails]);

    const handleTimeUpdate = useCallback(() => {
      const video = videoRef.current;
      if (!video || isScrubbingRef.current) return;
      // const t = video.currentTime;

      let t = video.currentTime;
      const limit =
        maxDuration && maxDuration > 0 ? maxDuration : video.duration;
      if (t >= limit) {
        t = limit;
        video.currentTime = limit;
        video.pause(); // 自動暫停
        setIsPlaying(false);
      }

      setCurrentTime(t);
      emitPlaybackTime(t);
    }, [emitPlaybackTime]);

    useEffect(() => {
      const video = videoRef.current;
      if (!video) return;
      video.addEventListener("timeupdate", handleTimeUpdate);
      return () => video.removeEventListener("timeupdate", handleTimeUpdate);
    }, [handleTimeUpdate]);

    const togglePlay = () => {
      const video = videoRef.current;
      if (!video) return;
      if (video.paused) void video.play();
      else video.pause();
    };

    const toggleMute = () => setIsMuted((v) => !v);

    const onVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const next = Number(e.target.value);
      const clamped = Math.min(1, Math.max(0, next));
      setVolume(clamped);
      if (clamped > 0) setIsMuted(false);
    };

    useEffect(() => {
      const video = videoRef.current;
      if (!video) return;
      video.playbackRate = playbackRate;
    }, [playbackRate]);

    const onSpeedChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setPlaybackRate(Number(e.target.value));
    };

    const getTimeFromPointerClientX = useCallback(
      (clientX: number) => {
        const el = progressBarRef.current;
        const limit = getTimelineLimit();
        if (!el || limit <= 0) return 0;

        const rect = el.getBoundingClientRect();
        if (rect.width <= 0) return 0;

        const ratio = (clientX - rect.left) / rect.width;
        return Math.min(limit, Math.max(0, ratio * limit));
      },
      [getTimelineLimit],
    );

    // 確保游標、playbar、progressLine 對齊
    const onKeyframePointerDown = useCallback(
      (e: React.PointerEvent<HTMLDivElement>) => {
        if (e.pointerType === "mouse" && e.button !== 0) return;
        if (getTimelineLimit() <= 0) return;
        e.preventDefault();
        const t = getTimeFromPointerClientX(e.clientX);
        seekTo(t);
      },
      [getTimelineLimit, getTimeFromPointerClientX, seekTo],
    );

    const endScrub = useCallback(
      (e: React.PointerEvent<HTMLDivElement>) => {
        if (!isScrubbingRef.current) return;
        isScrubbingRef.current = false;
        const bar = progressBarRef.current;
        if (bar?.hasPointerCapture(e.pointerId)) {
          bar.releasePointerCapture(e.pointerId);
        }
        const video = videoRef.current;
        const hasMedia =
          !!video && Number.isFinite(video.duration) && video.duration > 0;
        const t = hasMedia ? video.currentTime : (scrubTime ?? currentTime);
        setScrubTime(null);
        setCurrentTime(t);
        emitPlaybackTime(t);
      },
      [emitPlaybackTime, scrubTime, currentTime],
    );

    const onProgressPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerType === "mouse" && e.button !== 0) return;
      if (getTimelineLimit() <= 0) return;
      e.preventDefault();
      e.currentTarget.setPointerCapture(e.pointerId);
      isScrubbingRef.current = true;
      const t = getTimeFromPointerClientX(e.clientX);
      const video = videoRef.current;
      if (video && Number.isFinite(video.duration)) video.currentTime = t;
      setScrubTime(t);
      setCurrentTime(t);
      emitPlaybackTime(t);
    };

    const onProgressPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
      if (!isScrubbingRef.current) return;
      const t = getTimeFromPointerClientX(e.clientX);
      const video = videoRef.current;
      if (video && Number.isFinite(video.duration)) video.currentTime = t;
      setScrubTime(t);
      emitPlaybackTime(t);
    };

    const onProgressKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      const limit = getTimelineLimit();
      if (limit <= 0) return;
      const video = videoRef.current;
      const hasMedia =
        !!video && Number.isFinite(video.duration) && video.duration > 0;
      const step = 5;
      let t = hasMedia ? video.currentTime : (scrubTime ?? currentTime);
      let handled = false;
      if (e.key === "ArrowLeft") {
        t = Math.max(0, t - step);
        handled = true;
      } else if (e.key === "ArrowRight") {
        t = Math.min(limit, t + step);
        handled = true;
      } else if (e.key === "Home") {
        t = 0;
        handled = true;
      } else if (e.key === "End") {
        t = limit;
        handled = true;
      }
      if (handled) {
        e.preventDefault();
        if (hasMedia) video.currentTime = t;
        setCurrentTime(t);
        emitPlaybackTime(t);
      }
    };

    useEffect(() => {
      const video = videoRef.current;
      if (!video) return;
      video.volume = volume;
      video.muted = isMuted || volume === 0;
    }, [volume, isMuted]);

    const displayTime = scrubTime ?? currentTime;
    const stripHighlightSeconds =
      chartHighlightSeconds != null &&
      Number.isFinite(chartHighlightSeconds) &&
      chartHighlightSeconds >= 0
        ? chartHighlightSeconds
        : displayTime;

    const progressPct = progressFraction * 100;
    const isThumbPressed = scrubTime !== null;
    const isThumbEnlarged = isThumbHovered && !isThumbPressed;

    const activeThumbIndex =
      thumbnails.length > 0
        ? Math.min(
            thumbnails.length - 1,
            Math.floor(stripHighlightSeconds / THUMB_INTERVAL_SEC),
          )
        : -1;

    const totalChartWidth = plotboxWidth;
    const totalThumbs = thumbnails.length; // 總張數 N

    // 高度固定為 h-[132px]， 16:9 寬高比計算寬度
    const activeThumbWidthPx = 132 * (16 / 9);

    // Non-active Thumbnail 寬度 = (總寬 - Active) / (N - 1)
    const nonActiveThumbWidthPx =
      totalThumbs > 1
        ? (totalChartWidth - activeThumbWidthPx) / (totalThumbs - 1)
        : 0;

    useEffect(() => {
      const master = syncScrollRef?.current;
      const slave = keyframeStripRef.current;
      if (!master || !slave) return;

      const onScroll = () => {
        requestAnimationFrame(() => {
          slave.scrollLeft = master.scrollLeft;
        });
      };

      slave.scrollLeft = master.scrollLeft;

      master.addEventListener("scroll", onScroll, { passive: true });
      return () => master.removeEventListener("scroll", onScroll);
    }, [syncScrollRef]);

    // 每 6 分鐘一格，色階循環使用
    const placeholderTiles = useMemo(() => {
      if (!showPlaceholderStrip) return [];
      const total = maxDuration && maxDuration > 0 ? maxDuration : duration;
      const count =
        total > 0
          ? Math.max(1, Math.ceil(total / THUMB_INTERVAL_SEC))
          : PLACEHOLDER_COLORS.length;

      return Array.from(
        { length: count },
        (_, i) => PLACEHOLDER_COLORS[i % PLACEHOLDER_COLORS.length],
      );
    }, [showPlaceholderStrip, maxDuration, duration]);

    const activePlaceholderIndex =
      placeholderTiles.length > 0
        ? Math.min(
            placeholderTiles.length - 1,
            Math.floor(stripHighlightSeconds / THUMB_INTERVAL_SEC),
          )
        : -1;

    // Non-active 色塊寬度 = (總寬 - Active) / (N - 1)
    const placeholderTileWidthPx =
      placeholderTiles.length > 1
        ? (totalChartWidth - activeThumbWidthPx) / (placeholderTiles.length - 1)
        : 0;

    useEffect(() => {
      const master = syncScrollRef?.current;
      const slave = keyframeStripRef.current;
      if (!master || !slave) return;

      const onScroll = () => {
        slave.scrollLeft = master.scrollLeft;
      };

      master.addEventListener("scroll", onScroll, { passive: true });
      return () => master.removeEventListener("scroll", onScroll);
    }, [syncScrollRef]);

    const activeThumbSrc =
      activeThumbIndex >= 0 ? thumbnails[activeThumbIndex] : null;

    // 沒有影片可播放時，播放相關控制項一律停用
    const mediaControlsDisabled = showPlaceholderStrip;

    const previewContent = showPlaceholderStrip ? (
      <div
        className={`h-full w-full rounded-[4px] ${
          placeholderTiles[Math.max(activePlaceholderIndex, 0)] ??
          PLACEHOLDER_COLORS[0]
        }`}
      />
    ) : activeThumbSrc ? (
      <img
        src={activeThumbSrc}
        alt="active-keyframe"
        className="h-full w-full object-cover object-center rounded-[4px]"
      />
    ) : null;

    // 尚未開始上課時沒有錄播檔，只顯示提示文字
    if (status === "pending") {
      return (
        <section className="h-[214px] bg-[rgba(6,45,65,0.1)] rounded-[12px] flex items-center justify-center">
          <p className="body-2-reg text-gray-70">尚無錄播內容</p>
        </section>
      );
    }

    return (
      <section className="h-[214px] bg-[rgba(6,45,65,0.1)] pt-[13px] pb-1 pl-[44px] rounded-[12px] flex flex-col justify-between">
        <video
          ref={videoRef}
          src={videoSrc || undefined}
          className="hidden"
          playsInline
          crossOrigin="anonymous"
          onLoadedMetadata={handleLoadedMetadata}
          onError={() => setVideoLoadFailed(true)}
          onPlay={() => setIsPlaying(true)}
          onPause={() => setIsPlaying(false)}
          onEnded={() => setIsPlaying(false)}
        />

        <div
          ref={keyframeStripRef}
          className="w-full overflow-x-hidden overflow-y-visible flex-1 flex flex-col justify-start"
          style={{
            paddingLeft: yAxisGutterPx, // 對齊 EngagementChart 的 Y 軸
            boxSizing: "border-box",
            maxWidth: "100%",
          }}
        >
          <div
            className="flex flex-col overflow-x-auto overflow-y-visible min-w-0 scroll-smooth 
                      [&::-webkit-scrollbar]:hidden [scrollbar-width:none]"
            style={{
              width: `${totalChartWidth + RIGHT_MARGIN}px`,
            }}
          >
            <div
              className="h-[132px] flex items-center mb-2.5 ml-[8px] cursor-pointer touch-none select-none"
              style={{
                width: `${totalChartWidth}px`,
                boxSizing: "border-box",
              }}
              onPointerDown={onKeyframePointerDown}
            >
              {showPlaceholderStrip &&
                placeholderTiles.map((color, i) => {
                  const isActive = i === activePlaceholderIndex;

                  return (
                    <div
                      key={i}
                      data-kf-index={i}
                      style={{
                        width: `${isActive ? activeThumbWidthPx : placeholderTileWidthPx}px`,
                        flexShrink: 0,
                      }}
                      className={`relative h-[132px] overflow-hidden box-border pointer-events-none ${color} ${
                        isActive
                          ? "border-[2px] border-inset border-gray-40 z-10"
                          : "border-none"
                      }`}
                    />
                  );
                })}

              {thumbnails.map((src, i) => {
                const isActive = i === activeThumbIndex;
                const currentWidth = isActive
                  ? activeThumbWidthPx
                  : nonActiveThumbWidthPx;

                return (
                  <div
                    key={i}
                    data-kf-index={i}
                    style={{
                      width: `${currentWidth}px`,
                      flexShrink: 0,
                    }}
                    className={`relative h-[132px] overflow-hidden box-border pointer-events-none ${
                      isActive
                        ? "border-[2px] border-inset border-gray-40 z-10"
                        : "border-none"
                    }`}
                  >
                    <img
                      src={src}
                      alt={`thumb-${i}`}
                      style={{ width: "100%" }}
                      className="absolute left-0 top-0 h-full object-cover object-left max-w-none"
                      draggable={false}
                    />
                  </div>
                );
              })}
            </div>

            {/* 影片 Playbar*/}
            <div
              className="relative mb-2 ml-[8px] z-30 overflow-visible"
              style={{
                width: `${totalChartWidth}px`,
                boxSizing: "border-box",
              }}
            >
              <div
                ref={progressBarRef}
                role="slider"
                tabIndex={0}
                aria-label="影片進度"
                aria-valuemin={0}
                aria-valuemax={Math.floor(duration) || 0}
                aria-valuenow={Math.floor(displayTime)}
                className="h-[6px] bg-white rounded-full w-full relative z-30 cursor-pointer touch-none select-none outline-none overflow-visible"
                onPointerDown={onProgressPointerDown}
                onPointerMove={onProgressPointerMove}
                onPointerUp={endScrub}
                onPointerCancel={endScrub}
                onKeyDown={onProgressKeyDown}
              >
                <div
                  className={`absolute top-0 left-0 h-full bg-blue-70 rounded-full flex items-center justify-end ${
                    scrubTime === null
                      ? "transition-[width] duration-150 ease-out"
                      : ""
                  }`}
                  style={{ width: `${progressPct}%` }}
                />
                <div
                  className={`absolute top-1/2 z-50 flex items-center justify-center w-10 h-10 -translate-x-1/2 -translate-y-1/2 ${
                    scrubTime === null
                      ? "transition-[left] duration-150 ease-out"
                      : ""
                  }`}
                  style={{ left: `${progressPct}%` }}
                  onPointerEnter={() => setIsThumbHovered(true)}
                  onPointerLeave={() => setIsThumbHovered(false)}
                  onPointerDown={onProgressPointerDown}
                >
                  <div
                    className={`rounded-full transition-[width,height,background-color] duration-200 ease-out ${
                      isThumbPressed
                        ? "w-4 h-4 bg-blue-80"
                        : isThumbEnlarged
                          ? "w-5 h-5 bg-blue-60"
                          : "w-4 h-4 bg-blue-70"
                    }`}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* 底部固定控制列 */}
        <div className="h-[40px] flex items-center justify-between">
          <div className="flex items-center gap-2">
            {/* 播放/暫停按鈕 */}
            <Tooltip
              content={isPlaying ? "暫停" : "播放"}
              showQuestionMark={false}
              showArrow={false}
              triggerMode="hover"
            >
              <div
                className={`flex items-center h-9 rounded-full transition-all duration-300 px-1.5 ${
                  mediaControlsDisabled
                    ? "opacity-40 pointer-events-none"
                    : "hover:bg-[rgba(6,45,65,0.05)]"
                }`}
              >
                <button
                  type="button"
                  className="cursor-pointer"
                  onClick={togglePlay}
                  disabled={mediaControlsDisabled}
                  aria-label={isPlaying ? "暫停" : "播放"}
                >
                  <Image
                    src={
                      isPlaying
                        ? "/icon/function/icon_pause_filled.svg"
                        : "/icon/function/icon_play_filled.svg"
                    }
                    alt=""
                    width={24}
                    height={24}
                    className="shrink-0 select-none"
                  />
                </button>
              </div>
            </Tooltip>
            {/* 音量調節器 */}
            <Tooltip
              content={"音量"}
              showQuestionMark={false}
              showArrow={false}
              triggerMode="hover"
            >
              <div
                className={`group flex items-center h-9 rounded-full transition-all duration-300 px-1.5 ${
                  mediaControlsDisabled
                    ? "opacity-40 pointer-events-none"
                    : "hover:bg-[rgba(6,45,65,0.05)]"
                }`}
              >
                <button
                  type="button"
                  onClick={toggleMute}
                  disabled={mediaControlsDisabled}
                  className="text-gray-600 cursor-pointer"
                  aria-label={isMuted || volume === 0 ? "取消靜音" : "靜音"}
                >
                  {isMuted || volume === 0 ? (
                    <>
                      <Image
                        src="/icon/function/icon_volume-mute.svg"
                        alt=""
                        width={24}
                        height={24}
                        className="shrink-0 select-none block group-hover:hidden"
                      />
                      <Image
                        src="/icon/function/icon_volume-mute_filled.svg"
                        alt=""
                        width={24}
                        height={24}
                        className="shrink-0 select-none hidden group-hover:block"
                      />
                    </>
                  ) : (
                    <>
                      <Image
                        src="/icon/function/icon_volume.svg"
                        alt=""
                        width={24}
                        height={24}
                        className="shrink-0 select-none block group-hover:hidden"
                      />
                      <Image
                        src="/icon/function/icon_volume_filled.svg"
                        alt=""
                        width={24}
                        height={24}
                        className="shrink-0 select-none hidden group-hover:block"
                      />
                    </>
                  )}
                </button>
                <input
                  aria-label="volume"
                  type="range"
                  min={0}
                  max={1}
                  step={0.01}
                  value={isMuted ? 0 : volume}
                  onChange={onVolumeChange}
                  disabled={mediaControlsDisabled}
                  className="w-0 opacity-100 overflow-hidden group-hover:w-24 group-hover:ml-1 transition-all duration-300 ease-in-out accent-gray-700 cursor-pointer origin-left"
                />
              </div>
            </Tooltip>

            {/* 播放時間顯示 */}
            <span className="text-sm font-medium text-gray-90 tabular-nums">
              {/* {formatTime(displayTime)} / {formatTime(duration)} */}
              {formatTime(displayTime)} /{" "}
              {formatTime(
                maxDuration && maxDuration > 0 ? maxDuration : duration,
              )}
            </span>
          </div>

          {/* 速度調節器 */}
          <Tooltip
            content={"播放速度"}
            showQuestionMark={false}
            showArrow={false}
            triggerMode="hover"
          >
            <div
              className={`group flex items-center h-9 rounded-full transition-all duration-300 px-2 mr-[24px] relative ${
                mediaControlsDisabled
                  ? "opacity-40 pointer-events-none"
                  : "hover:bg-[rgba(6,45,65,0.05)]"
              }`}
            >
              <div className="relative flex items-center">
                <div className="absolute -top-1 left-1/2 -translate-x-1/2 text-[10px] font-medium text-gray-90 opacity-0 group-hover:opacity-100 transition-all duration-300 pointer-events-none tabular-nums whitespace-nowrap">
                  {playbackRate.toFixed(2)}x
                </div>
                <input
                  aria-label="speed"
                  type="range"
                  min={0.5}
                  max={2.5}
                  step={0.25}
                  value={playbackRate}
                  onChange={onSpeedChange}
                  disabled={mediaControlsDisabled}
                  className="w-0 opacity-0 overflow-hidden mt-2 group-hover:w-24 group-hover:mr-2 group-hover:opacity-100 transition-all duration-300 ease-in-out accent-gray-700 cursor-pointer origin-right"
                />
              </div>
              <div className="text-gray-600 flex items-center justify-center cursor-pointer">
                <Image
                  src="/icon/function/icon_speed.svg"
                  alt="speed"
                  width={24}
                  height={24}
                  className="shrink-0 select-none"
                />
              </div>
            </div>
          </Tooltip>
        </div>

        {previewContainer &&
          previewContent &&
          createPortal(
            <div className="box-border h-full w-full rounded-[12px] border-4 border-[rgba(6,45,65,0.3)] p-2 overflow-hidden bg-white">
              {previewContent}
            </div>,
            previewContainer,
          )}
      </section>
    );
  },
);

