1	using FutureClassroom.Api.Models;
2	using FutureClassroom.Core.Data;
3	using FutureClassroom.Core.Enumeration;
4	using Microsoft.EntityFrameworkCore;
5	using System.Text.Json;
6	
7	namespace FutureClassroom.Api.Services;
8	
9	public class CourseService(AppDbContext db)
10	{
11	    // Shown as the lesson topic when a course has no Lessons schedule metadata
12	    // and we fall back to listing raw AiResults instead.
13	    private const string NoScheduleTopicPlaceholder = "課程網無課程進度資訊";
14	
15	    private static readonly JsonSerializerOptions _caseInsensitive = new()
16	    {
17	        PropertyNameCaseInsensitive = true,
18	        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower
19	    };
20	
21	    public async Task<CoursesResponse> GetCoursesAsync(string? semester)
22	    {
23	        var query = db.Courses.AsQueryable();
24	        if (semester is not null)
25	            query = query.Where(c => c.Semester == semester);
26	
27	        var rawCourses = await query
28	            .Select(c => new { c.CourseId, c.Name, c.Section, c.CourseKey, c.SchedulesJson, c.Semester })
29	            .ToListAsync();
30	
31	        var courseKeys = rawCourses.Select(c => c.CourseKey).ToList();
32	
33	        var lessonStats = await db.AiResults
34	            .Where(r => courseKeys.Contains(r.CourseKey))
35	            .GroupBy(r => r.CourseKey)
36	            .Select(g => new
37	            {
38	                CourseKey = g.Key,
39	                Total = g.Count(),
40	                Completed = g.Count(r => r.IsScreenshotGenerated)
41	            })
42	            .ToDictionaryAsync(x => x.CourseKey, x => x);
43	
44	        var semesters = rawCourses
45	            .GroupBy(c => c.Semester)
46	            .OrderByDescending(g => g.Key)
47	            .Select(g => new SemesterDto(
48	                g.Key,
49	                g.Select(c => new CourseDto(
50	                    CourseId: c.CourseId,
51	                    CourseName: c.Name,
52	                    CourseSection: c.Section ?? "",
53	                    CourseKey: c.CourseKey,
54	                    CourseSchedule: c.SchedulesJson is null
55	                        ? []
56	                        : JsonSerializer.Deserialize<List<CourseScheduleDto>>(c.SchedulesJson, _caseInsensitive) ?? [],
57	                    TotalLessons: lessonStats.TryGetValue(c.CourseKey, out var s) ? s.Total : 0,
58	                    Completed: lessonStats.TryGetValue(c.CourseKey, out var s2) ? s2.Completed : 0
59	                )).ToList()
60	            ))
61	            .ToList();
62	
63	        return new CoursesResponse(semesters);
64	    }
65	
66	    public async Task<CourseLessonsResponse?> GetCourseLessonsAsync(string courseKey)
67	    {
68	        var course = await db.Courses
69	            .Where(c => c.CourseKey == courseKey)
70	            .FirstOrDefaultAsync()
71	            ?? throw new KeyNotFoundException($"Course not found: {courseKey}");
72	
73	        var rawLessons = await db.Lessons
74	            .Where(l => l.CourseKey == courseKey)
75	            .OrderBy(l => l.WeekNumber)
76	            .Select(l => new { l.LessonId, l.WeekNumber, l.LessonDate, l.Topic, l.UpdatedAt })
77	            .ToListAsync();
78	
79	        var isFallbackSchedule = rawLessons.Count == 0;
80	        List<LessonSummaryDto> lessons;
81	
82	        if (!isFallbackSchedule)
83	        {
84	            var lessonIds = rawLessons.Select(l => l.LessonId).ToList();
85	            var aiResults = await db.AiResults
86	                .Where(r => lessonIds.Contains(r.LessonId))
87	                .Select(r => new { r.LessonId, r.IsScreenshotGenerated, r.UpdatedAt })
88	                .ToDictionaryAsync(r => r.LessonId);
89	
90	            lessons = rawLessons.Select(l =>
91	            {
92	                var status = LessonEnum.LessonStatus.pending;
93	                string? lastUpdatedAt = null;
94	
95	                if (aiResults.TryGetValue(l.LessonId, out var ai))
96	                {
97	                    status = ai.IsScreenshotGenerated ? LessonEnum.LessonStatus.completed : LessonEnum.LessonStatus.analyzing;
98	                    lastUpdatedAt = ai.IsScreenshotGenerated ? ai.UpdatedAt.ToString("o") : null;
99	                }
100	
101	                return new LessonSummaryDto(
102	                    LessonId: l.LessonId,
103	                    WeekNumber: l.WeekNumber,
104	                    LessonDate: l.LessonDate.ToString("yyyy-MM-dd"),
105	                    Topic: l.Topic,
106	                    Status: status.ToString(),
107	                    LastUpdatedAt: lastUpdatedAt
108	                );
109	            }).ToList();
110	        }
111	        else
112	        {
113	            // The school's course website never sent us a Lessons schedule for this
114	            // course. Fall back to whatever AI analysis results already exist so the
115	            // list isn't empty. LessonDate/RecordDate are optional fields on the AI
116	            // push payload and are often blank, but GeneratedAt is always set — it's
117	            // what the ingestion endpoint uses to build LessonId in the first place
118	            // (see AiResultEndpoints) — so it's the reliable date source here. Rows
119	            // with neither are skipped rather than shown as a blank row.
120	            var fallbackResults = await db.AiResults
121	                .Where(r => r.CourseKey == courseKey && (r.LessonDate != null || r.GeneratedAt != null))
122	                .Select(r => new { r.LessonId, r.Week, r.LessonDate, r.GeneratedAt, r.IsScreenshotGenerated, r.UpdatedAt })
123	                .ToListAsync();
124	
125	            lessons = fallbackResults
126	                .Select(r =>
127	                {
128	                    var status = r.IsScreenshotGenerated ? LessonEnum.LessonStatus.completed : LessonEnum.LessonStatus.analyzing;
129	                    var lessonDate = r.LessonDate ?? DateOnly.FromDateTime(r.GeneratedAt!.Value);
130	
131	                    return new LessonSummaryDto(
132	                        LessonId: r.LessonId,
133	                        WeekNumber: int.TryParse(r.Week, out var week) ? week : 0,
134	                        LessonDate: lessonDate.ToString("yyyy-MM-dd"),
135	                        Topic: NoScheduleTopicPlaceholder,
136	                        Status: status.ToString(),
137	                        LastUpdatedAt: r.IsScreenshotGenerated ? r.UpdatedAt.ToString("o") : null
138	                    );
139	                })
140	                .OrderBy(l => l.LessonDate)
141	                .ToList();
142	        }
143	
144	        var schedules = course.SchedulesJson is null
145	            ? []
146	            : JsonSerializer.Deserialize<List<CourseScheduleDto>>(course.SchedulesJson, _caseInsensitive) ?? [];
147	
148	        return new CourseLessonsResponse(
149	            CourseId: course.CourseId,
150	            CourseName: course.Name,
151	            CourseSection: course.Section ?? "",
152	            CourseKey: courseKey,
153	            CourseSchedule: schedules,
154	            MaxCapacity: course.TotalStudentQuota,
155	            EnrolledCount: 0,
156	            Lessons: lessons,
157	            IsFallbackSchedule: isFallbackSchedule
158	        );
159	    }
160	}

