using FutureClassroom.Api.Models;
using FutureClassroom.Core.Data;
using FutureClassroom.Core.Enumeration;
using Microsoft.EntityFrameworkCore;
using System.Text.Json;

namespace FutureClassroom.Api.Services;

public class CourseService(AppDbContext db)
{
    // Shown as the lesson topic when a course has no Lessons schedule metadata
    // and we fall back to listing raw AiResults instead.
    private const string NoScheduleTopicPlaceholder = "課程網無課程進度資訊";

    private static readonly JsonSerializerOptions _caseInsensitive = new()
    {
        PropertyNameCaseInsensitive = true,
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower
    };

    public async Task<CoursesResponse> GetCoursesAsync(string? semester)
    {
        var query = db.Courses.AsQueryable();
        if (semester is not null)
            query = query.Where(c => c.Semester == semester);

        var rawCourses = await query
            .Select(c => new { c.CourseId, c.Name, c.Section, c.CourseKey, c.SchedulesJson, c.Semester })
            .ToListAsync();

        var courseKeys = rawCourses.Select(c => c.CourseKey).ToList();

        var lessonStats = await db.AiResults
            .Where(r => courseKeys.Contains(r.CourseKey))
            .GroupBy(r => r.CourseKey)
            .Select(g => new
            {
                CourseKey = g.Key,
                Total = g.Count(),
                Completed = g.Count(r => r.IsScreenshotGenerated)
            })
            .ToDictionaryAsync(x => x.CourseKey, x => x);

        var semesters = rawCourses
            .GroupBy(c => c.Semester)
            .OrderByDescending(g => g.Key)
            .Select(g => new SemesterDto(
                g.Key,
                g.Select(c => new CourseDto(
                    CourseId: c.CourseId,
                    CourseName: c.Name,
                    CourseSection: c.Section ?? "",
                    CourseKey: c.CourseKey,
                    CourseSchedule: c.SchedulesJson is null
                        ? []
                        : JsonSerializer.Deserialize<List<CourseScheduleDto>>(c.SchedulesJson, _caseInsensitive) ?? [],
                    TotalLessons: lessonStats.TryGetValue(c.CourseKey, out var s) ? s.Total : 0,
                    Completed: lessonStats.TryGetValue(c.CourseKey, out var s2) ? s2.Completed : 0
                )).ToList()
            ))
            .ToList();

        return new CoursesResponse(semesters);
    }

    public async Task<CourseLessonsResponse?> GetCourseLessonsAsync(string courseKey)
    {
        var course = await db.Courses
            .Where(c => c.CourseKey == courseKey)
            .FirstOrDefaultAsync()
            ?? throw new KeyNotFoundException($"Course not found: {courseKey}");

        var rawLessons = await db.Lessons
            .Where(l => l.CourseKey == courseKey)
            .OrderBy(l => l.WeekNumber)
            .Select(l => new { l.LessonId, l.WeekNumber, l.LessonDate, l.Topic, l.UpdatedAt })
            .ToListAsync();

        var isFallbackSchedule = rawLessons.Count == 0;
        List<LessonSummaryDto> lessons;

        if (!isFallbackSchedule)
        {
            var lessonIds = rawLessons.Select(l => l.LessonId).ToList();
            var aiResults = await db.AiResults
                .Where(r => lessonIds.Contains(r.LessonId))
                .Select(r => new { r.LessonId, r.UpdatedAt })
                .ToDictionaryAsync(r => r.LessonId);

            // "Completed" means the analysis result (AiWindows/AiWindowSeats) actually
            // exists — not whether a screenshot thumbnail happens to have been
            // generated yet (that's a separate, unrelated background job).
            var lessonIdsWithAnalysis = (await db.AiWindows
                .Where(w => lessonIds.Contains(w.LessonId))
                .Select(w => w.LessonId)
                .Distinct()
                .ToListAsync())
                .ToHashSet();

            lessons = rawLessons.Select(l =>
            {
                var status = LessonEnum.LessonStatus.pending;
                string? lastUpdatedAt = null;

                if (aiResults.TryGetValue(l.LessonId, out var ai))
                {
                    status = lessonIdsWithAnalysis.Contains(l.LessonId) ? LessonEnum.LessonStatus.completed : LessonEnum.LessonStatus.analyzing;
                    lastUpdatedAt = status == LessonEnum.LessonStatus.completed ? ai.UpdatedAt.ToString("o") : null;
                }

                return new LessonSummaryDto(
                    LessonId: l.LessonId,
                    WeekNumber: l.WeekNumber,
                    LessonDate: l.LessonDate.ToString("yyyy-MM-dd"),
                    Topic: l.Topic,
                    Status: status.ToString(),
                    LastUpdatedAt: lastUpdatedAt
                );
            }).ToList();
        }
        else
        {
            // The school's course website never sent us a Lessons schedule for this
            // course. Fall back to whatever AI analysis results already exist so the
            // list isn't empty. LessonDate/RecordDate are optional fields on the AI
            // push payload and are often blank, but GeneratedAt is always set — it's
            // what the ingestion endpoint uses to build LessonId in the first place
            // (see AiResultEndpoints) — so it's the reliable date source here. Rows
            // with neither are skipped rather than shown as a blank row.
            var fallbackResults = await db.AiResults
                .Where(r => r.CourseKey == courseKey && (r.LessonDate != null || r.GeneratedAt != null))
                .Select(r => new { r.LessonId, r.Week, r.LessonDate, r.GeneratedAt, r.UpdatedAt })
                .ToListAsync();

            var fallbackLessonIds = fallbackResults.Select(r => r.LessonId).ToList();
            var fallbackLessonIdsWithAnalysis = (await db.AiWindows
                .Where(w => fallbackLessonIds.Contains(w.LessonId))
                .Select(w => w.LessonId)
                .Distinct()
                .ToListAsync())
                .ToHashSet();

            lessons = fallbackResults
                .Select(r =>
                {
                    var status = fallbackLessonIdsWithAnalysis.Contains(r.LessonId) ? LessonEnum.LessonStatus.completed : LessonEnum.LessonStatus.analyzing;
                    var lessonDate = r.LessonDate ?? DateOnly.FromDateTime(r.GeneratedAt!.Value);

                    return new LessonSummaryDto(
                        LessonId: r.LessonId,
                        WeekNumber: int.TryParse(r.Week, out var week) ? week : 0,
                        LessonDate: lessonDate.ToString("yyyy-MM-dd"),
                        Topic: NoScheduleTopicPlaceholder,
                        Status: status.ToString(),
                        LastUpdatedAt: status == LessonEnum.LessonStatus.completed ? r.UpdatedAt.ToString("o") : null
                    );
                })
                .OrderBy(l => l.LessonDate)
                .ToList();
        }

        var schedules = course.SchedulesJson is null
            ? []
            : JsonSerializer.Deserialize<List<CourseScheduleDto>>(course.SchedulesJson, _caseInsensitive) ?? [];

        return new CourseLessonsResponse(
            CourseId: course.CourseId,
            CourseName: course.Name,
            CourseSection: course.Section ?? "",
            CourseKey: courseKey,
            CourseSchedule: schedules,
            MaxCapacity: course.TotalStudentQuota,
            EnrolledCount: 0,
            Lessons: lessons,
            IsFallbackSchedule: isFallbackSchedule
        );
    }
}

