"use client";

import Image from "@/components/AppImage";
import { Button } from "@/components/ui/Button";
import { useRouter } from "next/navigation";

interface LogOutDialogProps {
  open: boolean;
  onClose: () => void;
}

export default function LogOutDialog({ open, onClose }: LogOutDialogProps) {
  const router = useRouter();
  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-end md:items-center justify-center">
      {/* Background overlay */}
      <div
        className="absolute inset-0 bg-black/80 backdrop-blur-[8px]"
        onClick={onClose}
      />

      {/* Modal */}
      <div
        className="
        relative z-10 bg-white p-[32px] shadow-xl
        w-full md:w-[504px] 
        h-screen md:h-auto
        md:rounded-[24px] 
        border border-[rgba(99,226,253,0.3)] md:border-2
        flex flex-col
      "
      >
        {/* Header */}
        <div className="flex flex-col justify-between items-center gap-[16px]">
          <Image
            src="/images/img_status-logout.svg"
            alt="Logout"
            width={200}
            height={144}
          />
          <div className="flex flex-col items-center gap-[8px] mb-[40px]">
            <p className="title-2 text-gray-90">確定要登出？</p>
            <p className="body-1-reg text-gray-70">
              登出後需重新登入，才能查看課堂互動分析內容唷。
            </p>
          </div>
        </div>

        <div className="flex justify-center items-center gap-[16px] mt-auto md:mt-0 w-full">
          <Button
            variant="primary"
