} from "@/utils/recentlyViewed";

type LatestLessonApiItem = {
  lesson_id: string;
  course_key: string;
  course_name: string;
  course_id: string;
  course_section: string;
  course_schedule: {
    weekday?: string;
    start_session: string;
    end_session: string;
  }[];
  lesson_date?: string | null;
  generated_at?: string | null;
  created_at?: string | null;
};

type LatestLessonCardItem = {
  name: string;
  date: string;
  course_key: string;
  course_id: string;
  class: string;
  schedule: string;
  lesson_id: string;
  generated_at?: string | null;
};

type NotificationType = keyof typeof notificationConfig;

type NotificationItemData = {
  id: number;
  type: NotificationType;
  date: string;
  contentKey: string;
  isNew: boolean;
};

// TODO: 從 API 獲取通知
const NOTIFICATIONS: NotificationItemData[] = [
  {
    id: 1,
    type: "system",
    date: "2026 / 06 / 14  10:00",
    contentKey: "home.notif1",
    isNew: true,
  },
  {
    id: 2,
    type: "update",
    date: "2026 / 06 / 13  14:20",
    contentKey: "home.notif2",
    isNew: false,
  },
  {
    id: 3,
    type: "personal",
    date: "2026 / 06 / 05  18:45",
    contentKey: "home.notif3",
    isNew: false,
  },
  {
    id: 4,
    type: "general",
    date: "2026 / 06 / 04  10:00",
    contentKey: "home.notif4",
    isNew: false,
  },
  {
    id: 5,
    type: "general",
    date: "2026 / 06 / 02  09:15",
    contentKey: "home.notif5",
    isNew: false,
  },
];

const DISPLAY_NAME = "庭妤";

function greetingKeyForHour(hour: number) {
  if (hour < 12) return "home.greetingMorning";
  if (hour < 18) return "home.greetingAfternoon";
  return "home.greetingEvening";
}

export default function HomePage() {
  const { t, locale } = useI18n();
  const [currentPage, setCurrentPage] = useState(0); // 目前分頁狀態（從第 0 頁開始）
  const [latestAnalyzedCourses, setLatestAnalyzedCourses] = useState<
    LatestLessonCardItem[]
  >([]);
  const [recentlyViewedLessons, setRecentlyViewedLessons] = useState<
    RecentlyViewedLesson[]
  >([]);
  const [lastUpdatedAt, setLastUpdatedAt] = useState<string | null>(null);
  const itemsPerPage = 4;
  const totalPages = Math.ceil(NOTIFICATIONS.length / itemsPerPage); // 計算總頁數（以 {itemsPerPage} 則通知為一頁）
  const unreadCount = NOTIFICATIONS.filter((n) => n.isNew).length;

  useEffect(() => {
    const fetchLatestLessons = async () => {
      try {
        const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";
        const response = await fetch(`${basePath}/api/lessons/latest?limit=4`, {
          method: "GET",
          headers: { accept: "*/*" },
        });

        if (!response.ok) {
          throw new Error("Failed to fetch latest lessons");
        }

        const resBody = await response.json();
        const lessons = Array.isArray(resBody?.lessons) ? resBody.lessons : [];
        const mappedLessons = lessons.map(
          (lesson: LatestLessonApiItem): LatestLessonCardItem => ({
            name: lesson.course_name,
            date: formatDate(lesson.generated_at, locale),
            course_key: lesson.course_key,
            course_id: lesson.course_id,
            class: lesson.course_section,
            schedule: formatCourseSchedule(lesson.course_schedule, locale),
            lesson_id: lesson.lesson_id,
            generated_at: lesson.generated_at,
          }),
        );

        setLatestAnalyzedCourses(mappedLessons);
        setLastUpdatedAt(lessons[0]?.generated_at ?? null);
      } catch (error) {
        console.error(error);
      }
    };

    fetchLatestLessons();
  }, [locale]);

  useEffect(() => {
    setRecentlyViewedLessons(getRecentlyViewedLessons(4));
  }, []);

  // 當使用者拉大螢幕時，自動把分頁歸零，避免 RWD 切換時出錯
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 1024) {
        setCurrentPage(0);
      }
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // 根據目前頁數，裁切出要顯示的通知
  const startIndex = currentPage * itemsPerPage;
  const pagedNotifications = NOTIFICATIONS.slice(
    startIndex,
    startIndex + itemsPerPage,
  );

  const [activeNotification, setActiveNotification] =
    useState<NotificationItemData | null>(null);

  return (
    <div className="flex min-h-screen bg-[#F2F2F2] text-slate-700 font-sans">
      <main className="flex-1 p-4 md:p-8 flex flex-col lg:flex-row gap-6 items-stretch">
        <div className="flex-1 lg:flex-[3] flex flex-col gap-4 lg:max-h-[calc(100vh-64px)]">
          <section className="relative h-[326px] rounded-[24px] p-10 flex flex-col justify-center overflow-hidden shrink-0">
            <Image
              src="/images/img_banner-w.svg"
              alt={t("home.bannerAlt")}
              fill
              priority
              className="object-cover object-right z-0 hidden md:block"
            />
            <Image
              src="/images/img_banner-m.svg"
              alt={t("home.bannerAlt")}
              fill
              priority
              className="object-cover object-right z-0 md:hidden"
            />
            <div className="relative">
              <h1 className="large-title-1 mb-2 text-gray-90">
                {t(greetingKeyForHour(getTaiwanHour()), {
                  name: DISPLAY_NAME,
                })}
              </h1>
              <p className="body-1-reg text-slate-600">
                {lastUpdatedAt
                  ? t("home.lastUpdated", {
                      date: formatFullDate(lastUpdatedAt, locale),
                    })
                  : t("home.lastUpdatedEmpty")}
              </p>
            </div>
          </section>

          <div className="grid grid-cols-[1.2fr_1fr] max-md:grid-cols-1 gap-4 flex-1 max-h-[calc(100vh-326px)] max-md:max-h-none overflow-hidden">
            <DataCard
              title={t("home.latestAnalysis")}
              data={latestAnalyzedCourses}
              hasChart
              sortByField="date"
              sortOrder="desc"
            />
            <DataCard
              title={t("home.recentlyViewed")}
              data={recentlyViewedLessons}
              hasLastCheckedAt
              sortByField="last_checked_at"
              sortOrder="desc"
            />
          </div>
        </div>
        <aside className="w-full lg:w-auto lg:flex-1 bg-[rgba(6,45,65,0.05)] rounded-[32px] p-6 flex flex-col lg:max-h-[calc(100vh-64px)] lg:sticky lg:top-8">
          {/* TODO: 顯示未讀通知數量 */}
          <h2 className="headline-3-sb text-gray-90">
            {t("home.notifications", { count: unreadCount })}
          </h2>
          <div className="flex justify-end mb-2">
            {/* TODO: 全部標記為已讀功能 */}
            <button className="body-2-reg text-blue-70 underline cursor-pointer">
              {t("home.markAllRead")}
            </button>
          </div>
          <div className="flex-1 overflow-x-auto lg:overflow-y-auto space-y-2 pr-1 custom-scrollbar">
            {/* 在 lg 以上顯示「全部通知」；lg 以下只顯示「裁切後的該頁通知」 */}
            <div className="hidden lg:block space-y-2">
              {NOTIFICATIONS.map((n) => (
                <NotificationItem
                  key={n.id}
                  date={n.date}
                  type={n.type}
                  content={t(n.contentKey)}
                  onClick={() => setActiveNotification(n)}
                  isNew={n.isNew}
                />
              ))}
            </div>

            <div className="block lg:hidden space-y-2">
              {pagedNotifications.map((n) => (
                <NotificationItem
                  key={n.id}
                  date={n.date}
                  type={n.type}
                  content={t(n.contentKey)}
                  onClick={() => setActiveNotification(n)}
                  isNew={n.isNew}
                />
              ))}
            </div>
            {totalPages > 1 && (
              <div className="flex lg:hidden justify-center items-center gap-2 mt-4">
                {Array.from({ length: totalPages }).map((_, index) => {
                  const isActive = index === currentPage;
                  return (
                    <button
                      key={index}
                      type="button"
                      onClick={() => setCurrentPage(index)}
                      className={`transition-all duration-300 rounded-full cursor-pointer focus:outline-none ${
                        isActive
                          ? "w-4 h-1.5 bg-blue-70"
                          : "w-1.5 h-1.5 bg-gray-300 hover:bg-gray-400"
                      }`}
                      aria-label={t("home.goToPage", { page: index + 1 })}
                    />
                  );
                })}
              </div>
            )}
          </div>
        </aside>
      </main>
      {activeNotification && (
        <NotificationDialog
          isOpen={activeNotification !== null}
          onClose={() => setActiveNotification(null)}
          title={t(notificationConfig[activeNotification.type].titleKey)}
          date={activeNotification.date}
          icon={notificationConfig[activeNotification.type].icon}
          content={t(activeNotification.contentKey)}
        />
      )}
    </div>
  );
}

